/* ============================================================
   ARCHIVUS — THE DOCTRINES: every major political ideology,
   where it sits, where it came from, and what it begat.
   ------------------------------------------------------------
   One list of NODES drives four views (Compass, Lineage, Atlas,
   Library). A node is either
     · an IDEOLOGY  — has a family `f` and compass coordinates
                      x (economic: −10 left … +10 right) and
                      y (social: −10 libertarian … +10 authoritarian),
                      or `xc: 1` + `span` when it cuts across the chart;
     · a ROOT       — a thinker, text, organisation or event that
                      ideologies descend from (kind `k`: t/o/e).
   Common fields
     id, n (name), ln (lineage lane), yr (year of origin; negative = BCE),
     ap (1 = approximate date), pl (place of origin), at [lat, lon],
     w (who), tx (founding text), d (what it holds — in its own terms),
     c (what critics say / the record), u (source code, see url()),
     tu (link to the primary text), ref (id of an existing archive record),
     fr [[parentId, kind, note]] — kind s = source / descends from,
                                        x = written against / breaks with,
                                        p = split from,
     p (label priority 1–3), s [spreadX, spreadY] (how far adherents range),
     red (1 = member of the Marxist family compared in The Red Family),
     ar [importance, theme, region, civ] — lift this node into the main archive.

   PLACEMENTS ARE EDITORIAL. The two-axis chart is a convention
   (Nolan 1969; politicalcompass.org 2001), not a measurement.
   Coordinates follow where ideology charts customarily put each
   current; the spread halo shows how much its adherents range.
   Descriptions state each doctrine in its own terms, then its
   critics' case. No verdicts are given.
   ============================================================ */
(function () {
  "use strict";
  const N = [

  /* ───────────── COMMUNAL & UTOPIAN TRADITION ───────────── */
  { id: "plato", n: "Plato's Republic", k: "t", ln: "anc", yr: -375, ap: 1, pl: "Athens", at: [37.98, 23.73],
    d: "The guardians of the ideal city own nothing privately and raise their children in common — the oldest surviving argument that property corrupts those who rule.", u: "w:Republic_(Plato)" },
  { id: "acts", n: "The Jerusalem community of goods", k: "o", ln: "anc", yr: 35, ap: 1, pl: "Jerusalem", at: [31.78, 35.22],
    d: "The Acts of the Apostles (written c. 80–90) describes the first Christians holding all things in common and giving to each according to need — the passage every later Christian communist quoted.", u: "w:Christian_communism" },
  { id: "more", n: "Thomas More, Utopia", k: "t", ln: "anc", yr: 1516, pl: "Leuven (first printing)", at: [50.88, 4.70], fr: [["plato", "s"]],
    d: "An imagined island with no money and no private property. It named a genre — and gave Marx and Engels the adjective they would turn on their rivals.", u: "w:Utopia_(book)", ar: [4, "religion", "Europe", "England"] },
  { id: "muntzer", n: "Müntzer & the Peasants' War", k: "e", ln: "anc", yr: 1525, pl: "Frankenhausen, Thuringia", at: [51.36, 11.10], fr: [["acts", "s"]], ref: "reformation",
    d: "A radical Reformation preacher led Thuringian peasants under the watchword that all things are common. Engels wrote the episode up in 1850 as a mirror for the defeated revolutions of 1848.", u: "w:Thomas_Müntzer" },
  { id: "diggers", n: "Winstanley & the Diggers", k: "o", ln: "anc", yr: 1649, pl: "St George's Hill, Surrey", at: [51.35, -0.45], fr: [["acts", "s"], ["more", "s"]],
    d: "In the English Revolution, Gerrard Winstanley's 'True Levellers' planted crops on common land and declared the earth a common treasury for all.", u: "w:Diggers" },

  /* ───────────── FRANCE: REVOLUTION & EARLY SOCIALISM ───────────── */
  { id: "morelly", n: "Meslier, Morelly & Mably", k: "t", ln: "fr", yr: 1755, pl: "Paris", at: [48.86, 2.35], fr: [["more", "s"]],
    d: "Enlightenment writers who held private property to be the root of vice and drafted laws for a society without it. Morelly's Code of Nature (1755) was Babeuf's handbook.", u: "w:Étienne-Gabriel_Morelly" },
  { id: "rousseau", n: "Rousseau", k: "t", ln: "fr", yr: 1762, pl: "Geneva · Paris", at: [46.20, 6.15],
    tx: "Discourse on Inequality (1755); The Social Contract (1762)",
    d: "Traced inequality to the invention of private property and placed legitimate authority in the 'general will' of the people. Democrats, Jacobins, nationalists and socialists all claim him.", u: "s:rousseau" },
  { id: "leftright", n: "'Left' and 'Right' are born", k: "e", ln: "fr", yr: 1789, pl: "Versailles", at: [48.80, 2.12], ref: "frrev", fr: [["rousseau", "s"], ["locke", "s"]],
    d: "In the National Assembly of 1789, deputies who wanted the king to keep a veto sat to the president's right; those against sat to his left. The seating plan became the vocabulary of politics — and every modern ideology takes a position on this revolution.", u: "w:Left–right_political_spectrum" },
  { id: "jacobinism", n: "Jacobinism", f: "lib", x: -3.2, y: 5.8, ln: "fr", yr: 1793, pl: "Paris", at: [48.86, 2.35], p: 2, ref: "frrev",
    w: "Robespierre, Saint-Just, Marat", tx: "Constitution of the Year I (1793)", fr: [["rousseau", "s", "the general will"], ["leftright", "s"]],
    d: "The republic one and indivisible: popular sovereignty, universal male suffrage, price controls and public relief, enforced by a centralised emergency government — virtue backed by terror.",
    c: "Critics: the Terror of 1793–94 executed some 17,000 people after trial and made 'Jacobin' a byword for revolutionary dictatorship. Lenin took the comparison as a compliment.", u: "w:Jacobin_(politics)" },
  { id: "babouvism", n: "Babouvism", f: "com", x: -9.3, y: 3.0, ln: "fr", yr: 1796, pl: "Paris", at: [48.86, 2.35], p: 3,
    w: "Gracchus Babeuf, Sylvain Maréchal, Filippo Buonarroti", tx: "Manifesto of the Equals (1796)", fr: [["jacobinism", "s"], ["morelly", "s"]],
    d: "The Revolution stopped at equality before the law; real equality needs common ownership and equal distribution, to be won by an insurrection led by a secret directory. The Conspiracy of the Equals was betrayed and Babeuf guillotined in 1797.",
    c: "Critics: a levelling 'barracks communism' enforced by a self-appointed dictatorship — the objection later aimed at Blanqui and Lenin. Marx and Engels called it crude and ascetic, yet the first truly active communist party.", u: "w:Conspiracy_of_the_Equals", ar: [4, "law", "Europe", "France"] },
  { id: "fourier", n: "Charles Fourier", k: "t", ln: "fr", yr: 1808, pl: "Lyon", at: [45.76, 4.84],
    tx: "The Theory of the Four Movements (1808)",
    d: "Proposed cooperative 'phalansteries' where work would become attractive, attacked commerce as licensed fraud, and held that a society's progress is measured by the emancipation of its women — a line Marx and Engels repeated.", u: "w:Charles_Fourier" },
  { id: "saintsimon", n: "Henri de Saint-Simon", k: "t", ln: "fr", yr: 1821, pl: "Paris", at: [48.86, 2.35],
    tx: "The Industrial System (1821); The New Christianity (1825)",
    d: "Society should be run by its producers and scientists, not its idle owners; politics will become the science of production — the 'administration of things'. He also wrote of the struggle between classes.", u: "w:Henri_de_Saint-Simon" },
  { id: "classhist", n: "Thierry, Guizot & the historians of class", k: "t", ln: "fr", yr: 1825, ap: 1, pl: "Paris", at: [48.86, 2.35], fr: [["saintsimon", "s"]],
    d: "French liberal historians wrote the past of France and England as a struggle of classes — the Third Estate against the nobility. Marx said plainly (1852) that bourgeois historians had described the class struggle long before him.", u: "w:Augustin_Thierry" },
  { id: "blanc", n: "Louis Blanc, The Organisation of Labour", k: "t", ln: "fr", yr: 1839, pl: "Paris", at: [48.86, 2.35], fr: [["saintsimon", "s"], ["jacobinism", "s"]],
    d: "The democratic state should guarantee the right to work and finance 'social workshops' owned by their workers. Blanc sat in the 1848 Provisional Government and popularised the maxim 'from each according to ability, to each according to need'.", u: "w:Louis_Blanc" },
  { id: "blanquism", n: "Blanquism", f: "com", x: -7.2, y: 5.6, ln: "fr", yr: 1839, pl: "Paris", at: [48.86, 2.35], p: 3,
    w: "Louis Auguste Blanqui", tx: "Instructions for an Armed Uprising (1868)", fr: [["babouvism", "s", "through Buonarroti's history of the conspiracy (1828)"]],
    d: "A small, disciplined band of conspirators seizes power by a coup in the capital, then holds a temporary revolutionary dictatorship to educate the people. Blanqui spent more than thirty years in prison for trying.",
    c: "Critics: Engels called it revolution made by a handful on the class's behalf; 'Blanquism' became the standard Marxist charge against putschism — one the Mensheviks levelled at Lenin.", u: "w:Blanquism" },
  { id: "cabet", n: "Cabet & the word 'communism'", k: "t", ln: "fr", yr: 1840, pl: "Paris", at: [48.86, 2.35], fr: [["more", "s"], ["babouvism", "s"], ["owen", "s"], ["utopian", "s"]],
    d: "Étienne Cabet's novel Voyage to Icaria (1840) spread a peaceful, Christian 'communisme' among French workers just as the word entered print in the Paris secret societies. His followers sailed to found Icaria in America.", u: "w:Étienne_Cabet" },

  /* ───────────── PHILOSOPHY ───────────── */
  { id: "materialism", n: "The materialists: Epicurus to d'Holbach", k: "t", ln: "de", yr: 1770, pl: "Paris", at: [48.86, 2.35],
    d: "If people are formed by their circumstances, then change the circumstances. The French materialists (Helvétius, d'Holbach) drew the conclusion; Marx's doctoral thesis (1841) was on the ancient atomists Democritus and Epicurus.", u: "w:French_materialism" },
  { id: "hegel", n: "Hegel", k: "t", ln: "de", yr: 1807, pl: "Jena · Berlin", at: [50.93, 11.59],
    tx: "Phenomenology of Spirit (1807); Philosophy of Right (1821)",
    d: "History is a rational process that advances through contradiction — the dialectic — toward freedom, realised in the modern state. Marx kept the method and rejected the idealism: he said he found Hegel standing on his head and set him on his feet.", u: "s:hegel" },
  { id: "younghegel", n: "The Young Hegelians", k: "o", ln: "de", yr: 1838, ap: 1, pl: "Berlin", at: [52.52, 13.40], fr: [["hegel", "s"]],
    d: "Strauss, Bruno Bauer, Ruge, Hess, Stirner and the student Marx turned Hegel's method first on religion and then on the Prussian state. Censorship drove most of them into exile by 1843.", u: "w:Young_Hegelians" },
  { id: "feuerbach", n: "Feuerbach, The Essence of Christianity", k: "t", ln: "de", yr: 1841, pl: "Leipzig (publication)", at: [51.34, 12.37], fr: [["younghegel", "s"], ["materialism", "s"]],
    d: "God is humanity's own nature projected into the sky. Marx carried this idea of alienation from religion over to labour and money — then faulted Feuerbach (1845) for merely interpreting the world.", u: "w:Ludwig_Feuerbach" },
  { id: "hess", n: "Moses Hess", k: "t", ln: "de", yr: 1842, pl: "Cologne", at: [50.94, 6.96], fr: [["younghegel", "s"], ["saintsimon", "s"]],
    d: "The 'communist rabbi' who, by his own account, won Engels to communism in 1842 and worked beside Marx on the Rheinische Zeitung. He joined German philosophy to French socialism; later he wrote a founding text of Zionism.", u: "w:Moses_Hess" },
  { id: "stein", n: "Lorenz von Stein", k: "t", ln: "de", yr: 1842, pl: "Leipzig (publication)", at: [51.34, 12.37], fr: [["saintsimon", "s"], ["hegel", "s"]],
    d: "His Socialism and Communism of Present-Day France (1842) carried the French doctrines — and the concept of the proletariat as a class — to German readers. A conservative, he recommended a 'social monarchy' to forestall revolution.", u: "w:Lorenz_von_Stein" },
  { id: "weitling", n: "Weitling & the League of the Just", k: "o", ln: "de", yr: 1836, pl: "Paris → London", at: [48.86, 2.35], fr: [["babouvism", "s"], ["acts", "s"]],
    d: "A secret society of German journeymen in exile, founded in Paris in 1836. Its theorist, the tailor Wilhelm Weitling, preached a Christian communism of immediate revolution. Marx broke with him in Brussels in 1846: ignorance never yet helped anybody.", u: "w:League_of_the_Just" },

  /* ───────────── POLITICAL ECONOMY & BRITISH LABOUR ───────────── */
  { id: "physiocrats", n: "Quesnay & the Physiocrats", k: "t", ln: "pe", yr: 1758, pl: "Versailles", at: [48.80, 2.12],
    tx: "Tableau économique (1758)",
    d: "The first model of an economy as a circular flow among classes, and the first school to urge laissez-faire. Marx admired the Tableau and built his own schemes of reproduction on it.", u: "w:Physiocracy" },
  { id: "smith", n: "Adam Smith, The Wealth of Nations", k: "t", ln: "pe", yr: 1776, pl: "Kirkcaldy · London", at: [56.11, -3.16], ref: "wealthnations", fr: [["physiocrats", "s"]],
    d: "The division of labour, markets and self-interest as the engine of wealth; labour as the measure of value; three great classes living on wages, profit and rent.", u: "w:The_Wealth_of_Nations" },
  { id: "owen", n: "Robert Owen", k: "t", ln: "pe", yr: 1813, pl: "New Lanark, Scotland", at: [55.66, -3.78],
    tx: "A New View of Society (1813)",
    d: "A mill-owner who showed that shorter hours, schooling and decent housing paid — then moved on to cooperative villages (New Harmony, 1825) and trade unionism. 'Socialist' first appears in English in his followers' Co-operative Magazine (1827).", u: "w:Robert_Owen" },
  { id: "ricardo", n: "David Ricardo, Principles", k: "t", ln: "pe", yr: 1817, pl: "London", at: [51.51, -0.13], fr: [["smith", "s"]],
    d: "Made the labour theory of value rigorous and showed wages, profit and rent moving against one another — class antagonism stated in the language of economics.", u: "w:David_Ricardo" },
  { id: "sismondi", n: "Sismondi", k: "t", ln: "pe", yr: 1819, pl: "Geneva", at: [46.20, 6.15], fr: [["smith", "x"]],
    tx: "New Principles of Political Economy (1819)",
    d: "The first economist to argue that unchecked competition breeds crises of overproduction and a propertyless class — for which he revived the Roman word 'proletariat'. The Manifesto credits his diagnosis and rejects his remedy.", u: "w:Jean_Charles_Léonard_de_Sismondi" },
  { id: "ricsoc", n: "The Ricardian socialists", k: "t", ln: "pe", yr: 1825, pl: "London", at: [51.51, -0.13], fr: [["ricardo", "s"], ["owen", "s"]],
    d: "Thompson, Hodgskin, Gray and Bray drew the radical conclusion from Ricardo: if labour creates all value, labour is owed the whole product, and profit is a deduction from it.", u: "w:Ricardian_socialism" },
  { id: "chartism", n: "Chartism", k: "o", ln: "pe", yr: 1838, pl: "London · Birmingham · Manchester", at: [52.48, -1.90], fr: [["ricsoc", "s"], ["owen", "s"]],
    d: "The first mass political movement of the working class: millions signed petitions for the People's Charter — votes for all men, secret ballot, paid MPs. Marx and Engels took it as the model of a workers' party; a Chartist paper first printed the Manifesto in English.", u: "w:Chartism" },
  { id: "condition", n: "Engels, The Condition of the Working Class in England", k: "t", ln: "pe", yr: 1845, pl: "Manchester", at: [53.48, -2.24], ref: "industrial", fr: [["chartism", "s"], ["owen", "s"], ["hess", "s"]],
    d: "Sent at 22 to work in his father's cotton firm, Engels walked Manchester's slums and at 24 wrote the first great empirical study of industrial capitalism — the factory town as the nursery of the proletariat.", u: "w:The_Condition_of_the_Working_Class_in_England", tu: "m:archive/marx/works/1845/condition-working-class/" },

  /* ───────────── MARX & ENGELS: THE TRUNK ───────────── */
  { id: "paris1844", n: "Marx in Paris: the 1844 Manuscripts", k: "t", ln: "mx", yr: 1844, pl: "Paris", at: [48.86, 2.35], fr: [["feuerbach", "s", "alienation"], ["hess", "s"], ["ricardo", "s", "his first reading of the economists"], ["fourier", "s"]],
    d: "In exile in Paris, Marx met French workers' societies, read the economists and wrote of labour 'alienated' from its product. In August Engels called on him; they talked for ten days and worked together for forty years.", u: "w:Economic_and_Philosophic_Manuscripts_of_1844", tu: "m:archive/marx/works/1844/manuscripts/preface.htm" },
  { id: "gideology", n: "The German Ideology", k: "t", ln: "mx", yr: 1846, pl: "Brussels", at: [50.85, 4.35], fr: [["paris1844", "s"], ["younghegel", "x", "settling accounts with Bauer, Stirner and Feuerbach"], ["classhist", "s"], ["materialism", "s"], ["hegel", "s", "the dialectic, stripped of its idealism"]],
    d: "The first full statement of the materialist conception of history: how people produce their living shapes their law, politics and ideas. No publisher would take it; it was left, Marx said, to the gnawing criticism of the mice, and printed only in 1932.", u: "w:The_German_Ideology", tu: "m:archive/marx/works/1845/german-ideology/" },
  { id: "league", n: "The Communist League", k: "o", ln: "mx", yr: 1847, pl: "London", at: [51.51, -0.13], fr: [["weitling", "s", "the League of the Just, reorganised"], ["chartism", "s"], ["blanquism", "s"]],
    d: "In June 1847 the League of the Just, won over by Marx and Engels, renamed itself and swapped its motto 'All men are brothers' for 'Working men of all countries, unite!'. Its second congress (Nov–Dec 1847) commissioned a manifesto.", u: "w:Communist_League" },
  { id: "principles", n: "Engels, Principles of Communism", k: "t", ln: "mx", yr: 1847, pl: "Paris", at: [48.86, 2.35], fr: [["league", "s"], ["condition", "s"]],
    d: "Engels's draft for the League: twenty-five questions and answers in catechism form. He then suggested dropping the catechism and calling the thing a manifesto; Marx rewrote it in Brussels.", u: "w:Principles_of_Communism", tu: "m:archive/marx/works/1847/11/prin-com.htm" },
  { id: "marxism", n: "Classical Marxism", f: "com", x: -8.7, y: 0.2, s: [1.3, 3.4], ln: "mx", yr: 1848, pl: "Brussels → London", at: [51.51, -0.13], p: 1, red: 1,
    w: "Karl Marx, Friedrich Engels", tx: "Manifesto of the Communist Party (1848); Capital (1867)", tu: "m:archive/marx/works/1848/communist-manifesto/",
    fr: [["gideology", "s", "historical materialism"], ["principles", "s", "Engels's draft"], ["league", "s", "the organisation that commissioned it"], ["utopian", "s", "the goal, and the critique of competition, family and town-versus-country — minus the faith in goodwill"], ["ricsoc", "s", "the labour theory of value, turned into a theory of exploitation"], ["sismondi", "s", "crises of overproduction; the word 'proletariat'"], ["stein", "s"], ["mutualism", "x", "Proudhon, first admired, then demolished in The Poverty of Philosophy (1847)"]],
    d: "History is driven by struggle between classes defined by their place in production. Capitalism, the most productive system yet, exploits wage labour, breeds crises and creates the class that will abolish it — opening the way to a classless, stateless society.",
    c: "Critics: the predicted immiseration and collapse did not arrive in the industrial West; mainstream economics abandoned the labour theory of value; 'dictatorship of the proletariat' left the door open to dictatorship plain. Its height on the compass is itself disputed — a transitional workers' state, then no state at all — hence the tall halo.", u: "s:marx",
    ar: [8, "religion", "Europe", "German exiles", "The Communist Manifesto"] },
  { id: "intl1", n: "The First International", k: "o", ln: "mx", yr: 1864, pl: "St Martin's Hall, London", at: [51.51, -0.13], fr: [["marxism", "s"], ["chartism", "s"], ["mutualism", "s", "French Proudhonists were its largest early section"]],
    d: "The International Working Men's Association: English trade unionists, French Proudhonists, German exiles. Marx wrote its Inaugural Address and rules. It broke apart at The Hague in 1872, when Marx had Bakunin expelled, and was wound up in 1876.", u: "w:International_Workingmen's_Association", tu: "m:archive/marx/works/1864/10/27.htm", ar: [5, "law", "Europe", "International"] },
  { id: "capital", n: "Capital, volume I", k: "t", ln: "mx", yr: 1867, pl: "written in London, printed in Hamburg", at: [53.55, 9.99], fr: [["marxism", "s"], ["ricardo", "s"], ["physiocrats", "s"], ["condition", "s"]],
    d: "Twenty years in the British Museum's reading room: the commodity, surplus value as the secret of profit, the working day, machinery, and the 'general law of capitalist accumulation'. Volumes II and III were edited by Engels from Marx's drafts (1885, 1894).", u: "w:Das_Kapital", tu: "m:archive/marx/works/1867-c1/", ar: [6, "trade", "Europe", "German exiles", "Marx publishes Capital"] },
  { id: "commune71", n: "The Paris Commune", k: "e", ln: "mx", yr: 1871, pl: "Paris", at: [48.86, 2.35], ref: "commune", fr: [["blanquism", "s"], ["mutualism", "s"], ["intl1", "s"], ["jacobinism", "s"]],
    d: "For 72 days Paris governed itself through recallable delegates paid a worker's wage. Marx's The Civil War in France made it the model of working-class rule — and the 1872 preface to the Manifesto drew the lesson that workers cannot simply take over the ready-made state.", u: "w:Paris_Commune", tu: "m:archive/marx/works/1871/civil-war-france/" },
  { id: "gotha", n: "Gotha: one German party, and Marx's Critique", k: "e", ln: "mx", yr: 1875, pl: "Gotha", at: [50.95, 10.70], fr: [["lassalle", "s"], ["marxism", "s"]],
    d: "Lassalle's followers and the Marx-leaning 'Eisenachers' merged into what became the SPD. Marx's angry marginal notes on their programme distinguish two phases of communist society and speak of a 'revolutionary dictatorship of the proletariat'. Published only in 1891.", u: "w:Critique_of_the_Gotha_Programme", tu: "m:archive/marx/works/1875/gotha/" },
  { id: "antiduhring", n: "Anti-Dühring & 'scientific socialism'", k: "t", ln: "mx", yr: 1878, pl: "Leipzig (serialised in Vorwärts)", at: [51.34, 12.37], fr: [["marxism", "s"], ["capital", "s"], ["utopian", "x"]],
    d: "Engels's polemic became the textbook of a generation; three chapters, reissued as Socialism: Utopian and Scientific (1880), were the most widely read introduction to Marxism. Here the state is not 'abolished' — it dies out.", u: "w:Anti-Dühring", tu: "m:archive/marx/works/1880/soc-utop/" },
  { id: "intl2", n: "The Second International", k: "o", ln: "mx", yr: 1889, pl: "Paris", at: [48.86, 2.35], fr: [["intl1", "s"], ["antiduhring", "s"]],
    d: "A federation of mass socialist parties, the German SPD foremost. It gave the world May Day and the eight-hour demand, expelled the anarchists (1896), and pledged to answer war with strikes.", u: "w:Second_International" },
  { id: "orthodox", n: "Orthodox Marxism", f: "com", x: -7.5, y: 1.6, ln: "mx", yr: 1891, pl: "Erfurt", at: [50.98, 11.03], p: 3,
    w: "Karl Kautsky, August Bebel, Georgi Plekhanov", tx: "The Erfurt Programme (1891)", tu: "m:archive/kautsky/1892/erfurt/", fr: [["antiduhring", "s"], ["intl2", "s"], ["gotha", "s"]],
    d: "The Marxism of the Second International: capitalism's collapse is historically necessary, so the party should build a mass organisation, contest elections and let conditions ripen — in Kautsky's phrase, a revolutionary party but not a revolution-making one.",
    c: "Critics on the left (Luxemburg, Lenin) called it fatalism dressed as science and blamed it for August 1914; critics on the right (Bernstein) said its practice was already reformist and its theory should admit as much.", u: "w:Orthodox_Marxism" },
  { id: "warcredits", n: "4 August 1914: the International breaks", k: "e", ln: "mx", yr: 1914, pl: "Berlin", at: [52.52, 13.40], ref: "ww1", fr: [["intl2", "x"], ["orthodox", "s"]],
    d: "The SPD's deputies voted for the Kaiser's war credits; most socialist parties followed their own governments. A minority — Lenin, Luxemburg, Martov, Trotsky — met at Zimmerwald (1915) to oppose the war. Every later division of the left runs through this day.", u: "w:Burgfriedenspolitik" },

  /* ───────────── THE REFORM ROAD ───────────── */
  { id: "utopian", n: "Utopian socialism", f: "soc", x: -6.6, y: -5.6, ln: "ref", yr: 1825, pl: "Paris · New Lanark · New Harmony, Indiana", at: [38.13, -87.94], p: 2,
    w: "Saint-Simon, Fourier, Owen, Cabet", tx: "A New View of Society (Owen, 1813); The New Industrial World (Fourier, 1829)", fr: [["saintsimon", "s"], ["fourier", "s"], ["owen", "s"]],
    d: "A just society can be designed by reason and proved by example: model communities, cooperation instead of competition, education instead of class war. Dozens of colonies were founded, most of them in America.",
    c: "'Utopian' is Marx and Engels's label: they praised the critique and the vision but said appeals to goodwill ignore class interest. Nearly every colony failed within a few years.", u: "w:Utopian_socialism" },
  { id: "lassalle", n: "State socialism (Lassalle)", f: "soc", x: -4.2, y: 2.8, ln: "ref", yr: 1863, pl: "Leipzig", at: [51.34, 12.37], p: 3,
    w: "Ferdinand Lassalle", tx: "Open Reply Letter (1863)", fr: [["blanc", "s"], ["hegel", "s", "the state as ethical community"], ["marxism", "s"]],
    d: "The state is not the enemy but the instrument: win universal suffrage, then use public credit to fund workers' producer cooperatives. Lassalle founded Germany's first workers' party (1863) and bargained privately with Bismarck.",
    c: "Critics: Marx attacked its reliance on the Prussian state and its 'iron law of wages' in the Critique of the Gotha Programme; liberals saw in it the seed of an all-providing bureaucracy.", u: "w:Ferdinand_Lassalle" },
  { id: "fabian", n: "Fabianism", f: "soc", x: -3.8, y: 0.6, ln: "ref", yr: 1884, pl: "London", at: [51.51, -0.13], p: 3,
    w: "Sidney & Beatrice Webb, George Bernard Shaw, Graham Wallas", tx: "Fabian Essays in Socialism (1889)", fr: [["ricsoc", "s"], ["mill", "s"], ["georgism", "s"]],
    d: "Socialism will arrive by instalments — municipal ownership, regulation, expert administration — through the patient 'permeation' of existing parties and the civil service. The Society helped found the Labour Party (1900) and the London School of Economics.",
    c: "Critics: technocratic and paternalist — socialism done to people by experts. The Webbs' late admiration for Stalin's USSR and some early Fabians' enthusiasm for eugenics are held against it.", u: "w:Fabian_Society" },
  { id: "revisionism", n: "Revisionism (Bernstein)", f: "soc", x: -4.4, y: -0.8, ln: "ref", yr: 1899, pl: "written in London exile, published in Stuttgart", at: [48.78, 9.18], p: 2, red: 1,
    w: "Eduard Bernstein", tx: "The Preconditions of Socialism (1899)", tu: "m:reference/archive/bernstein/works/1899/evsoc/", fr: [["orthodox", "x"], ["fabian", "s", "Bernstein's London years"]],
    d: "Marx's forecasts need revising: capitalism is not collapsing, the middle classes are not vanishing and workers are not growing poorer. Socialism should be pursued as steady democratic reform — the movement matters more than the final goal.",
    c: "Critics: Kautsky and Luxemburg said it abandons socialism for a slightly kinder capitalism. The SPD formally condemned it in 1899 and 1903 while increasingly practising it.", u: "w:Eduard_Bernstein" },
  { id: "menshevism", n: "Menshevism", f: "soc", x: -7.1, y: -0.8, ln: "ref", yr: 1903, pl: "London (Second Congress of the RSDLP)", at: [51.51, -0.13], p: 1, red: 1,
    w: "Julius Martov, Pavel Axelrod, Fyodor Dan, Irakli Tsereteli; Plekhanov at times", tx: "Martov's draft of Rule 1 (1903); World Bolshevism (Martov, 1919)", tu: "m:archive/martov/", fr: [["rsdlp", "p"], ["orthodox", "s"], ["plekhanov", "s"]],
    d: "Orthodox Marxism applied to Russia: a backward country must first have a bourgeois-democratic revolution and a long capitalist development. The workers' party should be broad, open and democratic, pressing the liberals from the left rather than seizing power before its time.",
    c: "Critics: Bolsheviks said this meant tailing the liberals, and in 1917 it tied the Mensheviks to a Provisional Government that kept Russia in the war. They governed independent Georgia (1918–21) until the Red Army invaded; in Russia the party was suppressed by the early 1920s.", u: "b:Menshevik" },
  { id: "austromarx", n: "Austro-Marxism", f: "soc", x: -6.2, y: -2.2, ln: "ref", yr: 1904, pl: "Vienna", at: [48.21, 16.37], p: 3,
    w: "Otto Bauer, Max Adler, Karl Renner, Rudolf Hilferding", tx: "The Question of Nationalities and Social Democracy (Bauer, 1907)", fr: [["orthodox", "s"]],
    d: "A third course between reformism and Bolshevism: win power by the ballot, use force only in defence, and give each nation cultural autonomy inside a multinational state. 'Red Vienna' (1919–34) built it in brick — public housing, clinics, schools.",
    c: "Critics: Lenin and Stalin rejected cultural autonomy as dividing workers by nation; its caution is blamed for the defeat by Dollfuss's dictatorship in February 1934.", u: "w:Austromarxism" },
  { id: "socdem", n: "Social democracy", f: "soc", x: -3.2, y: -2.0, ln: "ref", yr: 1919, pl: "Weimar Berlin · Stockholm · Bad Godesberg", at: [59.33, 18.07], p: 1,
    w: "Friedrich Ebert, Hjalmar Branting, Per Albin Hansson, Clement Attlee, Willy Brandt, Olof Palme", tx: "Godesberg Programme (SPD, 1959)", fr: [["revisionism", "s"], ["warcredits", "p", "the pro-war majorities of 1914 become the governing parties of 1919"], ["keynes", "s"], ["fabian", "s"]],
    d: "Capitalism is to be tamed, not abolished: parliamentary democracy, strong unions, progressive taxation, a welfare state and a mixed economy. In 1959 the SPD dropped Marxism altogether — as much competition as possible, as much planning as necessary.",
    c: "Critics on the left: it manages capitalism and gave up the goal — and in 1919 turned the Freikorps on the revolutionary left. Critics on the right: high taxes and regulation blunt enterprise. Communists of the early 1930s called it 'social fascism'.", u: "b:social-democracy" },
  { id: "marketsoc", n: "Market socialism", f: "soc", x: -4.4, y: -2.9, ln: "ref", yr: 1936, pl: "Chicago · Kraków", at: [50.06, 19.94], p: 3,
    w: "Oskar Lange, Abba Lerner; later Alec Nove, John Roemer", tx: "On the Economic Theory of Socialism (Lange, 1936–37)", fr: [["mises", "x", "the socialist calculation debate"], ["mutualism", "s"]],
    d: "Public or cooperative ownership of firms can be combined with market prices and competition — answering the charge that socialism cannot calculate. Tried in part in Yugoslavia and in Hungary's New Economic Mechanism (1968).",
    c: "Critics: Hayek replied that markets without private owners lose the knowledge and incentives that make prices work; Marxists replied that markets reproduce inequality and unemployment.", u: "w:Market_socialism" },
  { id: "demsoc", n: "Democratic socialism", f: "soc", x: -5.6, y: -3.9, ln: "ref", yr: 1951, pl: "Frankfurt (Socialist International)", at: [50.11, 8.68], p: 1,
    w: "Aneurin Bevan, Salvador Allende, Michael Harrington, Tony Benn", tx: "Aims and Tasks of Democratic Socialism (1951)", fr: [["socdem", "s"], ["austromarx", "s"], ["fabian", "s"], ["ml", "x"]],
    d: "Social ownership or democratic control of the economy's commanding heights, reached and kept only through free elections, civil liberties and pluralism — against capitalism and against Soviet-style dictatorship alike.",
    c: "Critics on the right: wide public ownership erodes efficiency and, in time, liberty (Hayek). On the revolutionary left: a ruling class is not voted out — Allende's overthrow in 1973 is their exhibit.", u: "w:Democratic_socialism" },
  { id: "thirdway", n: "The Third Way", f: "soc", x: 1.4, y: 0.4, ln: "ref", yr: 1994, pl: "London · Washington", at: [51.51, -0.13], p: 3,
    w: "Anthony Giddens, Tony Blair, Bill Clinton, Gerhard Schröder", tx: "The Third Way (Giddens, 1998)", fr: [["socdem", "s"], ["neolib", "s"]],
    d: "Social democracy reconciled with globalised markets: accept privatisation and fiscal restraint, invest in education and opportunity, and trade welfare entitlements for 'rights and responsibilities'.",
    c: "Critics on the left: neoliberalism with a human face, which cut social-democratic parties off from their working-class voters. Critics on the right: presentation without principle.", u: "w:Third_Way" },

  /* ───────────── THE REVOLUTIONARY ROAD ───────────── */
  { id: "narodnik", n: "Russian populism (the Narodniks)", k: "o", ln: "rev", yr: 1861, pl: "St Petersburg · London exile", at: [59.94, 30.31], fr: [["fourier", "s"], ["blanquism", "s"], ["hegel", "s"]],
    d: "Herzen and Chernyshevsky held that Russia could reach socialism through the peasant commune, skipping capitalism. Students 'went to the people' (1874); Tkachev urged a conspiratorial seizure of power; the People's Will killed Tsar Alexander II (1881). Lenin's brother was hanged as one of them.", u: "w:Narodniks" },
  { id: "plekhanov", n: "Plekhanov & the first Russian Marxists", k: "o", ln: "rev", yr: 1883, pl: "Geneva", at: [46.20, 6.15], fr: [["narodnik", "x"], ["marxism", "s"]],
    d: "The Emancipation of Labour group, founded by ex-populists in Swiss exile, argued against the Narodniks that Russia could not skip capitalism and that the small working class, not the peasantry, would lead. Plekhanov taught Marxism to Lenin and Martov alike.", u: "w:Emancipation_of_Labour" },
  { id: "leninism", n: "Leninism (Bolshevism)", f: "com", x: -8.3, y: 6.2, ln: "rev", yr: 1902, pl: "written in exile (Munich, Geneva, Zürich), proven in Petrograd", at: [59.94, 30.31], p: 1, red: 1,
    w: "Vladimir Lenin", tx: "What Is To Be Done? (1902); Imperialism (1916); The State and Revolution (1917)", tu: "m:archive/lenin/works/1901/witbd/",
    fr: [["orthodox", "x", "accepted Kautsky's Marxism, rejected his patience; after 1914 called him a renegade"], ["narodnik", "s", "the conspiratorial party of Tkachev and the People's Will — minus their peasant socialism and their terrorism"], ["plekhanov", "s"], ["rsdlp", "p"]],
    d: "A disciplined vanguard party of professional revolutionaries brings socialist consciousness to the working class, allies it with the peasantry, smashes the existing state and rules through soviets. Imperialism makes revolution possible first at capitalism's weakest link.",
    c: "Critics: Luxemburg and Martov warned at once that the party would substitute itself for the class. The dissolution of the Constituent Assembly (January 1918), the Cheka, and the bans on other parties and on factions (1921) are cited as the root of Stalinism — a continuity that Trotskyists and many Leninists deny.", u: "b:Leninism" },
  { id: "rsdlp", n: "1903: Bolsheviks and Mensheviks", k: "e", ln: "rev", yr: 1903, pl: "Brussels → London", at: [50.85, 4.35], fr: [["plekhanov", "s"], ["orthodox", "s"]],
    d: "At the Second Congress of the Russian Social-Democratic Labour Party, Lenin and Martov split over one sentence — who counts as a member. Martov's looser wording won that vote; Lenin's group won the leadership elections after seven delegates walked out, and named itself 'the majority' (bolsheviki). The break became final at Prague in 1912.", u: "w:2nd_Congress_of_the_Russian_Social_Democratic_Labour_Party",
    ar: [5, "law", "Europe", "Russian exiles", "Bolsheviks and Mensheviks split"] },
  { id: "october", n: "October 1917", k: "e", ln: "rev", yr: 1917, pl: "Petrograd", at: [59.94, 30.31], ref: "russianrev", fr: [["leninism", "s"], ["warcredits", "s"]],
    d: "The Bolsheviks, with the Left SRs, overthrew the Provisional Government in the name of the soviets: peace, land, bread. In January 1918 they dispersed the elected Constituent Assembly, in which they had won about a quarter of the vote.", u: "w:October_Revolution" },
  { id: "comintern", n: "The Third International (Comintern)", k: "o", ln: "rev", yr: 1919, pl: "Moscow", at: [55.75, 37.62], fr: [["october", "s"], ["leninism", "s"], ["intl2", "x"]],
    d: "Founded to spread the revolution. Its Twenty-One Conditions (1920) made every socialist party choose — expel the reformists and accept Moscow's discipline, or stay out. Hence the worldwide division between Communist and Social Democratic parties. Stalin dissolved it in 1943.", u: "w:Communist_International", ar: [5, "law", "Global", "Soviet Russia"] },
  { id: "ml", n: "Marxism–Leninism (Stalinism)", f: "com", x: -8.5, y: 8.6, ln: "rev", yr: 1924, pl: "Moscow", at: [55.75, 37.62], p: 1, red: 1,
    w: "Joseph Stalin; codified in the Short Course (1938)", tx: "Foundations of Leninism (1924); History of the CPSU(B): Short Course (1938)", tu: "m:reference/archive/stalin/works/1924/foundations-leninism/", fr: [["leninism", "s"], ["comintern", "s"]],
    d: "The official doctrine of the USSR and the parties modelled on it: one ruling party, state ownership, central five-year plans, collectivised farms, and 'socialism in one country' — build it in the USSR first without waiting for world revolution. Stalin added that class struggle sharpens as socialism advances.",
    c: "Critics: the doctrine under which the terror, the Gulag and the famine of 1930–33 took place. Trotsky called it the ideology of a bureaucratic caste; Khrushchev (1956), a 'cult of personality'. Adherents credit it with industrialisation and the defeat of Nazi Germany. 'Stalinism' is its opponents' word.", u: "b:Stalinism",
    ar: [5, "law", "Europe", "Soviet Union", "'Socialism in one country': Stalin against Trotsky"] },
  { id: "titoism", n: "Titoism", f: "com", x: -6.0, y: 4.6, ln: "rev", yr: 1948, pl: "Belgrade", at: [44.80, 20.47], p: 2, red: 1,
    w: "Josip Broz Tito, Edvard Kardelj; Milovan Djilas, later its critic", tx: "Law on workers' self-management (1950)", fr: [["ml", "p", "expelled from the Cominform, 28 June 1948"]],
    d: "Each country finds its own road to socialism. Expelled by Stalin, Yugoslavia replaced central planning with enterprises run by elected workers' councils trading on a market, and led the Non-Aligned Movement between the blocs.",
    c: "Critics: still a one-party state with a prison island (Goli Otok). Moscow and Beijing called it revisionism; self-management left unemployment, regional inequality and foreign debt that the federation did not survive.", u: "w:Titoism",
    ar: [4, "law", "Europe", "Yugoslavia", "The Tito–Stalin split"] },
  { id: "juche", n: "Juche", f: "com", x: -6.4, y: 9.6, ln: "rev", yr: 1955, pl: "Pyongyang", at: [39.03, 125.75], p: 2, red: 1,
    w: "Kim Il Sung, Kim Jong Il", tx: "On Eliminating Dogmatism and Formalism and Establishing Juche (speech, 1955)", fr: [["ml", "s"], ["nationalism", "s"]],
    d: "'Self-reliance': the Korean nation, guided by a single Leader, is master of its own revolution — independence in politics, self-sufficiency in the economy, self-defence in arms. It displaced Marxism–Leninism in North Korea's constitution by stages (1972, 1992, 2009).",
    c: "Critics: a hereditary leader-cult and nationalism in socialist dress; many scholars doubt it is Marxist at all. The famine of the 1990s followed the loss of the Soviet aid on which self-reliance had depended.", u: "w:Juche" },
  { id: "secretspeech", n: "1956: the Secret Speech and Budapest", k: "e", ln: "rev", yr: 1956, pl: "Moscow · Budapest", at: [47.50, 19.04], fr: [["ml", "x"]],
    d: "In February Khrushchev told a closed session of the Twentieth Congress that Stalin had been a tyrant. In November Soviet tanks crushed the Hungarian revolution the speech helped set off. Communist parties everywhere lost members; Beijing called it revisionism; a New Left was born.", u: "w:On_the_Cult_of_Personality_and_Its_Consequences",
    ar: [6, "law", "Europe", "Soviet Union", "Khrushchev's Secret Speech and the Hungarian Revolution"] },
  { id: "sinosoviet", n: "The Sino-Soviet split", k: "e", ln: "rev", yr: 1960, pl: "Moscow · Beijing", at: [39.90, 116.40], fr: [["maoism", "s"], ["secretspeech", "x"]],
    d: "The two communist giants fell out over de-Stalinisation, 'peaceful coexistence' with the West, and who led the world movement. Soviet advisers left China in 1960; by 1969 the armies were shooting across the Ussuri. Parties from Albania to Peru had to choose.", u: "w:Sino-Soviet_split",
    ar: [5, "empire", "Global", "USSR / China"] },
  { id: "prague", n: "1968: the Prague Spring", k: "e", ln: "rev", yr: 1968, pl: "Prague", at: [50.08, 14.44], ref: "prague68", fr: [["secretspeech", "s"]],
    d: "Dubček's 'socialism with a human face' — a free press and rival voices inside a communist state — was ended by half a million Warsaw Pact troops. Moscow's claim of a right to intervene (the Brezhnev Doctrine) cost it the Western communist parties.", u: "w:Prague_Spring" },
  { id: "hoxhaism", n: "Hoxhaism", f: "com", x: -9.5, y: 9.5, ln: "rev", yr: 1978, pl: "Tirana", at: [41.33, 19.82], p: 3, red: 1,
    w: "Enver Hoxha", tx: "Imperialism and the Revolution (1978)", fr: [["ml", "s"], ["sinosoviet", "s", "sided with China in 1961"], ["maoism", "p", "broke with Beijing in 1978 over its opening to the United States"]],
    d: "Anti-revisionist Marxism–Leninism at its strictest: Stalin's line defended against Khrushchev's USSR, Tito's Yugoslavia and, after 1978, China as well. In Albania it meant near-total self-reliance and, from 1967, a ban on all religion.",
    c: "Critics: one of the most closed and repressive states in Europe, dotted with bunkers against invasions that never came. It left Albania the continent's poorest country.", u: "w:Hoxhaism" },
  { id: "perestroika", n: "Perestroika and the collapse", k: "e", ln: "rev", yr: 1985, pl: "Moscow · Berlin", at: [55.75, 37.62], ref: "ussrfall", fr: [["ml", "x"], ["prague", "s"], ["eurocom", "s"]],
    d: "Gorbachev tried openness (glasnost) and restructuring to save the system and declined to use the army to hold Eastern Europe. The regimes fell in 1989; the USSR dissolved in December 1991. Five party-states remain: China, Vietnam, Laos, Cuba and North Korea.", u: "w:Perestroika" },

  /* ───────────── DISSIDENT & WESTERN MARXISM ───────────── */
  { id: "luxemburgism", n: "Luxemburgism", f: "com", x: -8.7, y: -3.0, ln: "dis", yr: 1906, pl: "Berlin · Warsaw", at: [52.52, 13.40], p: 2, red: 1,
    w: "Rosa Luxemburg, Karl Liebknecht, Leo Jogiches", tx: "Reform or Revolution (1900); The Mass Strike (1906); The Russian Revolution (1918)", tu: "m:archive/luxemburg/1918/russian-revolution/",
    fr: [["orthodox", "s"], ["revisionism", "x", "Reform or Revolution answers Bernstein"], ["leninism", "x", "against the vanguard party (1904) and the suppression of democracy (1918)"]],
    d: "Revolution is made by the spontaneous mass action of workers — the mass strike — which the party should clarify, not command. Socialism requires the fullest democracy: freedom is always the freedom of the one who thinks differently.",
    c: "Critics: Leninists said she underrated organisation, and count the defeat of the Spartacist rising (January 1919), in which she was murdered, as the cost. Reformists said her insistence on revolution isolated the left. She never called her views an 'ism'.", u: "w:Luxemburgism" },
  { id: "councilcom", n: "Council communism", f: "com", x: -9.3, y: -5.4, ln: "dis", yr: 1920, pl: "Amsterdam · Berlin", at: [52.37, 4.90], p: 2, red: 1,
    w: "Anton Pannekoek, Herman Gorter, Otto Rühle, Paul Mattick", tx: "Open Letter to Comrade Lenin (Gorter, 1920); Workers' Councils (Pannekoek, 1947)", tu: "m:archive/pannekoe/1947/workers-councils.htm",
    fr: [["luxemburgism", "s"], ["leninism", "x", "the target of Lenin's 'Left-Wing' Communism: An Infantile Disorder (1920)"], ["syndicalism", "s"]],
    d: "Workers' councils elected at the point of production — not a party, a parliament or a union — are both the means of revolution and the form of the new society. The Bolshevik state is state capitalism run by a party bureaucracy.",
    c: "Critics: Lenin dismissed it as an 'infantile disorder' that abandons the parliaments and unions where workers actually are. It never held power or built a lasting mass organisation.", u: "w:Council_communism" },
  { id: "trotskyism", n: "Trotskyism", f: "com", x: -9.0, y: 4.6, ln: "dis", yr: 1923, pl: "Moscow → exile: Prinkipo, Coyoacán", at: [19.35, -99.16], p: 1, red: 1,
    w: "Leon Trotsky", tx: "Results and Prospects (1906); The Permanent Revolution (1930); The Revolution Betrayed (1936)", tu: "m:archive/trotsky/1936/revbet/",
    fr: [["leninism", "s"], ["ml", "x", "the Left Opposition (1923) against 'socialism in one country' and the party bureaucracy"]],
    d: "In backward countries the bourgeoisie is too weak to make its own revolution, so workers must lead it and carry straight on to socialist measures — which survive only if revolution spreads abroad ('permanent revolution'). The USSR is a workers' state degenerated under a bureaucracy that a political revolution must remove.",
    c: "Critics: Stalinists called it adventurism that would have staked the USSR on foreign revolutions. Anarchists and left communists recall Trotsky's own part in crushing Kronstadt (1921) and militarising labour. The movement has split repeatedly since his murder in 1940.", u: "b:Trotskyism" },
  { id: "westernmarx", n: "Western Marxism & critical theory", f: "com", x: -7.7, y: -4.4, ln: "dis", yr: 1923, pl: "Vienna · Frankfurt · a Fascist prison in Turi", at: [40.92, 17.02], p: 2,
    w: "Georg Lukács, Karl Korsch, Antonio Gramsci, Adorno, Horkheimer, Marcuse", tx: "History and Class Consciousness (1923); Prison Notebooks (1929–35); Dialectic of Enlightenment (1947)", tu: "m:archive/gramsci/",
    fr: [["marxism", "s", "a return to Hegel and the young Marx"], ["paris1844", "s"], ["leninism", "x"], ["luxemburgism", "s"]],
    d: "Why did revolution fail in the advanced West? Because capitalist rule works through culture and consent as much as force: 'hegemony', reification, the culture industry. Marxism is a method of criticism, not a science of iron laws.",
    c: "Critics: orthodox Marxists called it idealism (the Comintern condemned Lukács in 1924); others note its retreat from politics into philosophy. The right-wing phrase 'cultural Marxism' recasts it as a conspiracy — a claim historians reject.", u: "w:Western_Marxism" },
  { id: "newleft", n: "The New Left", f: "soc", x: -6.4, y: -6.9, ln: "dis", yr: 1960, pl: "London · Port Huron · Paris", at: [42.97, -82.43], p: 2,
    w: "E. P. Thompson, Stuart Hall, C. Wright Mills, Herbert Marcuse, Tom Hayden", tx: "Port Huron Statement (1962); One-Dimensional Man (Marcuse, 1964)", fr: [["westernmarx", "s"], ["secretspeech", "s"], ["trotskyism", "s"], ["anarchocom", "s"]],
    d: "Born of 1956: a left against both Stalinism and Cold War liberalism, widening the struggle from factory and wage to civil rights, war, sex, race, the university and everyday life. 'Participatory democracy'; May 1968.",
    c: "Critics on the old left: it traded class for culture and workers for students. Conservatives blame it for a permissive, fragmenting politics of identity. Some splinters turned to armed struggle in the 1970s.", u: "w:New_Left" },
  { id: "eurocom", n: "Eurocommunism", f: "com", x: -5.8, y: 0.4, ln: "dis", yr: 1975, pl: "Rome · Madrid · Paris", at: [41.90, 12.50], p: 2, red: 1,
    w: "Enrico Berlinguer, Santiago Carrillo, Georges Marchais", tx: "Eurocommunism and the State (Carrillo, 1977)", fr: [["ml", "p"], ["westernmarx", "s", "Gramsci's 'war of position'"], ["prague", "s"]],
    d: "Western Europe's communist parties can reach socialism through elections, pluralism and civil liberties, independent of Moscow — whose invasion of Czechoslovakia they condemned. Italy's PCI offered a 'historic compromise' with Christian Democracy.",
    c: "Critics: Moscow called it a surrender to social democracy; opponents at home doubted the conversion was sincere. The parties declined or dissolved after 1989.", u: "w:Eurocommunism" },

  /* ───────────── ASIA · AFRICA · LATIN AMERICA ───────────── */
  { id: "maoism", n: "Maoism", f: "com", x: -9.4, y: 7.5, ln: "tri", yr: 1927, pl: "Hunan → Jinggangshan → Yan'an", at: [28.23, 112.94], p: 1, red: 1, ref: "chinarev",
    w: "Mao Zedong; later Lin Biao, the 'Gang of Four', Abimael Guzmán", tx: "Report on the Peasant Movement in Hunan (1927); On Contradiction (1937); On New Democracy (1940)", tu: "m:reference/archive/mao/selected-works/date-index.htm",
    fr: [["ml", "s"], ["leninism", "s", "imperialism and the vanguard party — relocated to the countryside"], ["anticolonial", "s"]],
    d: "In an agrarian, semi-colonial country the peasantry, led by the Communist Party, is the main force of revolution: protracted people's war surrounds the cities from the countryside. Classes re-emerge under socialism and inside the party itself, so the revolution must continue — the 'mass line', the Cultural Revolution.",
    c: "Critics: the Great Leap Forward brought the deadliest famine on record and the Cultural Revolution a decade of persecution; the Chinese party itself ruled in 1981 that Mao's late errors were grave. Adherents cite national unification, land reform and steep rises in literacy and life expectancy.", u: "b:Maoism" },
  { id: "longmarch", n: "The Long March", k: "e", ln: "tri", yr: 1934, pl: "Jiangxi → Shaanxi", at: [36.60, 109.49], fr: [["maoism", "s"]],
    d: "Driven from their southern base, the Red Army walked some 9,000 kilometres in a year; perhaps one in ten who set out arrived. At Zunyi (January 1935) Mao took the lead from the Moscow-trained leadership; at Yan'an he wrote the doctrine.", u: "w:Long_March",
    ar: [5, "war", "East Asia", "Communist China"] },
  { id: "baathism", n: "Ba'athism & Arab socialism", f: "nat", x: -3.0, y: 7.2, ln: "tri", yr: 1947, pl: "Damascus", at: [33.51, 36.29], p: 3,
    w: "Michel Aflaq, Salah al-Din al-Bitar; Nasser in parallel", tx: "Constitution of the Ba'ath Party (1947)", fr: [["nationalism", "s"], ["anticolonial", "s"], ["ml", "s", "the single party and the plan — without class struggle or atheism"]],
    d: "'Unity, freedom, socialism': one Arab nation reborn (ba'ath) from the Atlantic to the Gulf — secular, with nationalised industry and land reform, in a socialism that explicitly rejects Marxist class war.",
    c: "Critics: in power it meant military one-party rule by rival Syrian and Iraqi branches — the Assads (1970–2024) and Saddam Hussein (1979–2003) — with mass repression and the use of chemical weapons.", u: "w:Ba'athism" },
  { id: "guevarism", n: "Guevarism & Castroism", f: "com", x: -7.4, y: 7.4, ln: "tri", yr: 1960, pl: "Sierra Maestra → Havana", at: [23.11, -82.37], p: 2, red: 1, ref: "cubarev",
    w: "Che Guevara, Fidel Castro, Régis Debray", tx: "Guerrilla Warfare (Guevara, 1960); Socialism and Man in Cuba (1965)", tu: "m:archive/guevara/1965/03/man-socialism.htm", fr: [["leninism", "s"], ["maoism", "s", "guerrilla war from the countryside"], ["anticolonial", "s"]],
    d: "A small guerrilla band (the foco) can itself create the conditions for revolution without waiting for a party or for history to ripen. Socialism should be built on moral incentives and a 'new man', with armed solidarity toward the Third World.",
    c: "Critics: the foco failed everywhere after Cuba — Guevara died attempting it in Bolivia (1967). Cuba became a one-party state dependent on Soviet subsidy, with executions and labour camps in the 1960s. Supporters cite literacy, medicine and defiance of the US embargo.", u: "w:Guevarism" },
  { id: "afrsoc", n: "African socialism (Ujamaa)", f: "soc", x: -5.8, y: 2.6, ln: "tri", yr: 1967, pl: "Arusha, Tanzania", at: [-3.37, 36.68], p: 3,
    w: "Julius Nyerere, Kwame Nkrumah, Léopold Senghor, Modibo Keïta", tx: "The Arusha Declaration (1967)", fr: [["anticolonial", "s"], ["fabian", "s"], ["ml", "s"]],
    d: "Socialism is rooted in Africa's own communal traditions and need not pass through class war or copy Europe: self-reliance, nationalised industry, villages farming together (ujamaa, 'familyhood').",
    c: "Critics: Tanzania's compulsory villagisation (1973–76) moved millions and cut harvests; single-party rule became the norm. Supporters cite literacy, national unity and peace across ethnic lines.", u: "w:African_socialism" },
  { id: "libtheo", n: "Liberation theology", f: "soc", x: -5.2, y: -1.7, ln: "tri", yr: 1968, pl: "Medellín (bishops' conference)", at: [6.25, -75.56], p: 3,
    w: "Gustavo Gutiérrez, Leonardo Boff, Óscar Romero", tx: "A Theology of Liberation (Gutiérrez, 1971)", fr: [["acts", "s"], ["marxism", "s", "class analysis, borrowed as a tool"], ["christdem", "x"]],
    d: "The Gospel demands a 'preferential option for the poor': sin is also structural, and salvation includes liberation from poverty and oppression. It organised 'base communities' across Latin America.",
    c: "Critics: the Vatican under John Paul II censured its use of Marxist concepts (1984); military regimes treated its priests as subversives and killed many, Archbishop Romero among them.", u: "w:Liberation_theology" },
  { id: "dengism", n: "Dengism (socialism with Chinese characteristics)", f: "com", x: -1.4, y: 8.0, s: [2.4, 1.2], ln: "tri", yr: 1978, pl: "Beijing", at: [39.90, 116.40], p: 2, red: 1, ref: "chinareform",
    w: "Deng Xiaoping, Chen Yun, Zhao Ziyang", tx: "Emancipate the Mind, Seek Truth from Facts (speech, December 1978)", fr: [["maoism", "x", "reverses the Cultural Revolution; keeps the party"], ["leninism", "s", "echoes the New Economic Policy of 1921"]],
    d: "China is in the 'primary stage of socialism', so developing the productive forces comes first: markets, private firms and foreign capital are tools, under the unbroken rule of the Communist Party.",
    c: "Critics on the left call it capitalist restoration under a red flag; liberal critics point to Tiananmen (1989) and the absence of political reform. Supporters point to the largest fall in poverty ever recorded.", u: "w:Deng_Xiaoping_Theory" },
  { id: "zapatismo", n: "Zapatismo", f: "ana", x: -7.5, y: -7.7, ln: "tri", yr: 1994, pl: "Chiapas, Mexico", at: [16.74, -92.64], p: 3,
    w: "The EZLN; Subcomandante Marcos", tx: "First Declaration of the Lacandon Jungle (1994)", fr: [["guevarism", "x", "began as a Guevarist foco, remade by the Maya communities"], ["anarchocom", "s"], ["libtheo", "s"]],
    d: "An indigenous uprising against NAFTA and five centuries of dispossession that chose not to seize the state: autonomous municipalities governed by rotating councils that 'lead by obeying'.",
    c: "Critics: autonomy has kept the communities poor and isolated; the Mexican state regards the zones as outside the law.", u: "w:Neozapatismo" },
  { id: "bolivarian", n: "Socialism of the 21st century", f: "soc", x: -4.9, y: 4.5, ln: "tri", yr: 1999, pl: "Caracas", at: [10.49, -66.88], p: 3,
    w: "Hugo Chávez, Evo Morales, Rafael Correa; the term is Heinz Dieterich's (1996)", fr: [["guevarism", "s"], ["populism", "s"], ["demsoc", "s"]],
    d: "Latin America's 'pink tide' in its radical form: elected presidents using oil and gas revenue for social programmes, nationalisations, new constitutions and communal councils, in Bolívar's name and against US influence.",
    c: "Critics: power gathered in the presidency, courts and media came under pressure, and Venezuela's economy collapsed after 2014, driving millions abroad. Supporters cite sharp falls in poverty in the 2000s and blame sanctions.", u: "w:Socialism_of_the_21st_century" },

  /* ───────────── ANARCHISM ───────────── */
  { id: "godwin", n: "William Godwin, Political Justice", k: "t", ln: "ana", yr: 1793, pl: "London", at: [51.51, -0.13], fr: [["leftright", "s"]],
    d: "The first philosophical case that government is an evil which reason will make unnecessary. Godwin never used the word 'anarchist'; the tradition claims him anyway.", u: "w:Enquiry_Concerning_Political_Justice" },
  { id: "mutualism", n: "Mutualism (Proudhon)", f: "ana", x: -4.6, y: -8.2, ln: "ana", yr: 1840, pl: "Paris — Proudhon was a printer from Besançon", at: [47.24, 6.02], p: 2,
    w: "Pierre-Joseph Proudhon", tx: "What Is Property? (1840)", fr: [["godwin", "s"], ["fourier", "s"], ["ricsoc", "s"]],
    d: "'Property is theft' when it means income without labour; possession by those who work is liberty. Free producers and cooperatives should exchange at cost through a people's bank lending without interest, and federate without a state. Proudhon was the first to call himself an anarchist.",
    c: "Critics: Marx's Poverty of Philosophy (1847) called it the dream of the small producer in an age of factories. Proudhon's antisemitism and hostility to women's equality are also held against him.", u: "w:Mutualism_(economic_theory)",
    ar: [4, "religion", "Europe", "France", "Proudhon: 'Property is theft'"] },
  { id: "indanarch", n: "Individualist anarchism & egoism", f: "ana", x: 2.0, y: -9.2, ln: "ana", yr: 1844, pl: "Berlin · Boston", at: [42.36, -71.06], p: 3,
    w: "Max Stirner, Josiah Warren, Benjamin Tucker, Lysander Spooner", tx: "The Ego and Its Own (Stirner, 1844); Liberty (Tucker's journal, 1881–1908)", fr: [["younghegel", "s"], ["mutualism", "s"], ["godwin", "s"]],
    d: "The sovereign individual owes nothing to state, church, nation or 'humanity' — all are phantoms. The American school added free markets without privilege: no state-backed monopolies of money, land, tariffs or patents.",
    c: "Critics: Marx and Engels spent most of The German Ideology mocking 'Saint Max'; social anarchists say it ignores economic power. It left no movement, though both the libertarian right and the anarchist left claim it.", u: "w:Individualist_anarchism" },
  { id: "collectivist", n: "Collectivist anarchism (Bakunin)", f: "ana", x: -8.6, y: -8.5, ln: "ana", yr: 1868, pl: "Geneva · the Jura · Saint-Imier", at: [47.15, 7.00], p: 2,
    w: "Mikhail Bakunin, James Guillaume", tx: "Statism and Anarchy (1873)", tu: "m:reference/archive/bakunin/works/1873/statism-anarchy.htm",
    fr: [["mutualism", "s"], ["intl1", "p", "the split at The Hague, 1872; the anti-authoritarian International met at Saint-Imier"], ["marxism", "x", "accepted Marx's economics, rejected his workers' state"]],
    d: "Abolish state and capital together, at once: land and workshops held collectively by free federations of producers. Any 'workers' state' will become the rule of a new class of officials and experts over the workers.",
    c: "Critics: Marx had Bakunin expelled from the International for running a secret society inside it; Marxists say abolishing the state overnight leaves a revolution defenceless. Bakunin's writing is marred by antisemitism.", u: "w:Collectivist_anarchism" },
  { id: "anarchocom", n: "Anarcho-communism", f: "ana", x: -9.6, y: -9.4, ln: "ana", yr: 1880, pl: "the Jura Federation, Switzerland", at: [47.10, 6.83], p: 1,
    w: "Peter Kropotkin, Élisée Reclus, Errico Malatesta, Emma Goldman", tx: "The Conquest of Bread (1892); Mutual Aid (1902)", fr: [["collectivist", "s"]],
    d: "No state, no wages, no money: free communes holding everything in common and distributing by need. Cooperation — 'mutual aid' — is as much a factor of evolution as competition.",
    c: "Critics: no account of how millions coordinate without prices or authority. Its brief practice (Makhno's Ukraine 1918–21, Aragon 1936–37) was crushed by enemies on both sides; the assassinations of the 1890s branded anarchism as terrorism.", u: "w:Anarcho-communism" },
  { id: "syndicalism", n: "Anarcho-syndicalism", f: "ana", x: -8.2, y: -6.8, ln: "ana", yr: 1906, pl: "Amiens · Chicago · Barcelona", at: [49.89, 2.30], p: 2,
    w: "Fernand Pelloutier, Rudolf Rocker; the CGT, IWW and CNT", tx: "Charter of Amiens (1906); Anarcho-Syndicalism (Rocker, 1938)", fr: [["collectivist", "s"], ["mutualism", "s"]],
    d: "The revolutionary trade union is both the weapon and the skeleton of the future society: direct action, no parties, and a general strike after which the unions run production themselves. In 1936 the CNT collectivised much of Catalonia and Aragon.",
    c: "Critics: Leninists said refusing politics leaves state power to the enemy. The Spanish experiment was suppressed by its Communist allies (May 1937) before Franco finished it; some syndicalists followed Sorel toward fascism.", u: "w:Anarcho-syndicalism" },
  { id: "communalism", n: "Communalism & democratic confederalism", f: "ana", x: -6.9, y: -8.9, ln: "ana", yr: 1982, pl: "Burlington, Vermont → Rojava", at: [44.48, -73.21], p: 3,
    w: "Murray Bookchin, Abdullah Öcalan", tx: "The Ecology of Freedom (Bookchin, 1982)", fr: [["anarchocom", "s"], ["newleft", "s"], ["greens", "s"]],
    d: "The domination of nature stems from the domination of people. Replace the nation-state with confederations of directly democratic municipal assemblies, ecological and feminist. Adopted by the Kurdish movement and applied in north-east Syria from 2012.",
    c: "Critics: assemblies do not scale; in Rojava one party dominates in practice, and wartime conscription sits uneasily with the theory.", u: "w:Murray_Bookchin" },

  /* ───────────── LIBERALISM & LIBERTARIANISM ───────────── */
  { id: "levellers", n: "The Levellers", k: "o", ln: "lib", yr: 1647, pl: "Putney, London", at: [51.46, -0.22],
    d: "Soldiers and pamphleteers of the English Revolution who demanded a written constitution, religious toleration and a vote for (nearly) every man: the poorest he in England has a life to live as the greatest he.", u: "w:Levellers" },
  { id: "locke", n: "John Locke, Two Treatises", k: "t", ln: "lib", yr: 1689, pl: "London", at: [51.51, -0.13], ref: "locke", fr: [["levellers", "s"], ["hobbes", "x"], ["absolutism", "x", "the First Treatise refutes Filmer"]],
    d: "Men hold natural rights to life, liberty and property; government is a trust that exists by consent and may be resisted when it breaks that trust.", u: "w:Two_Treatises_of_Government" },
  { id: "classlib", n: "Classical liberalism", f: "lib", x: 5.0, y: -4.4, ln: "lib", yr: 1776, pl: "London · Glasgow · Paris", at: [55.86, -4.25], p: 1,
    w: "John Locke, Adam Smith, Montesquieu, Benjamin Constant, Richard Cobden", tx: "Two Treatises of Government (1689); The Wealth of Nations (1776)", fr: [["locke", "s"], ["smith", "s"], ["absolutism", "x"]],
    d: "Individuals hold rights to life, liberty and property; government exists by consent to protect them and must be limited by law, representation and divided powers. Free markets and free trade turn self-interest into general prosperity.",
    c: "Critics: socialists — formal freedom is hollow for those with nothing to sell but their labour; conservatives — it dissolves community and custom. In practice it long coexisted with slavery, empire and a vote restricted to property-owners.", u: "b:liberalism" },
  { id: "republicanism", n: "Civic republicanism", f: "lib", x: 0.4, y: -2.4, ln: "lib", yr: 1776, pl: "Philadelphia", at: [39.95, -75.17], p: 3, ref: "amrev",
    w: "Machiavelli (the Discourses), James Harrington, Madison, Jefferson", tx: "Declaration of Independence (1776); The Federalist (1787–88)", fr: [["locke", "s"], ["rousseau", "s"]],
    d: "Liberty is not being left alone but not being dominated: citizens are free when they govern themselves under law, without kings or hereditary privilege. It needs civic virtue, balanced constitutions and vigilance against corruption.",
    c: "Critics: the 'people' of the early republics excluded women, the enslaved and the propertyless. Liberals fear that demands for civic virtue license coercion — the Jacobin temptation.", u: "s:republicanism" },
  { id: "radicalism", n: "Radicalism", f: "lib", x: -1.8, y: -4.3, ln: "lib", yr: 1791, pl: "London · Paris", at: [51.51, -0.13], p: 3,
    w: "Thomas Paine, Jeremy Bentham, the Chartists, Georges Clemenceau", tx: "Rights of Man (1791–92)", fr: [["classlib", "s"], ["levellers", "s"], ["leftright", "s"], ["burke", "x", "Rights of Man answers Burke"]],
    d: "Liberalism's democratic left wing: universal suffrage, a secular republic, free schooling, an end to aristocratic privilege — and, in Paine, the first sketch of old-age pensions and child benefit paid from a tax on estates.",
    c: "Critics: conservatives saw mob rule; socialists said it stopped at the factory gate and left property untouched.", u: "w:Radicalism_(historical)" },
  { id: "mill", n: "J. S. Mill, On Liberty", k: "t", ln: "lib", yr: 1859, pl: "London", at: [51.51, -0.13], fr: [["classlib", "s"], ["radicalism", "s"], ["saintsimon", "s"]],
    d: "The only ground for coercing anyone is to prevent harm to others. Mill also championed votes for women and, late in life, cooperative socialism — the hinge on which classical liberalism turns toward social liberalism.", u: "w:On_Liberty" },
  { id: "georgism", n: "Georgism", f: "lib", x: -0.2, y: -5.2, ln: "lib", yr: 1879, pl: "San Francisco", at: [37.77, -122.42], p: 3,
    w: "Henry George", tx: "Progress and Poverty (1879)", fr: [["ricardo", "s", "the theory of rent"], ["classlib", "s"]],
    d: "Land is nobody's product, so its rent belongs to everybody: replace other taxes with a single tax on land values and leave labour and capital free.",
    c: "Critics: land rent alone cannot fund a modern state and is hard to assess; Marx called it capitalism's last ditch. Economists from Friedman to Stiglitz have nonetheless called the land tax the least bad tax.", u: "w:Georgism" },
  { id: "sociallib", n: "Social liberalism", f: "lib", x: -2.0, y: -2.8, ln: "lib", yr: 1881, pl: "Oxford · London", at: [51.75, -1.26], p: 1, ref: "newdeal",
    w: "T. H. Green, L. T. Hobhouse, J. M. Keynes, William Beveridge, F. D. Roosevelt, John Rawls", tx: "Liberalism (Hobhouse, 1911); A Theory of Justice (Rawls, 1971)", fr: [["mill", "s"], ["radicalism", "s"], ["keynes", "s"]],
    d: "Freedom means the real capacity to shape one's life, which poverty, ignorance and insecurity destroy as surely as tyranny. The state should regulate markets, insure against unemployment, sickness and old age, and steady demand — within private ownership.",
    c: "Critics on the right: an ever-growing state erodes the liberty it promises (Hayek's 'road to serfdom'). Critics on the left: it treats symptoms and leaves ownership and power where they were.", u: "w:Social_liberalism" },
  { id: "mises", n: "Mises and the calculation problem", k: "t", ln: "lib", yr: 1920, pl: "Vienna", at: [48.21, 16.37], fr: [["classlib", "s"], ["marxism", "x"]],
    d: "Ludwig von Mises argued that without private ownership and market prices a planned economy cannot calculate what anything costs. Hayek extended the case; Lange's reply founded market socialism. It remains the central economic argument against socialism.", u: "w:Economic_calculation_problem" },
  { id: "ordolib", n: "Ordoliberalism (social market economy)", f: "lib", x: 3.4, y: -0.6, ln: "lib", yr: 1932, pl: "Freiburg", at: [47.99, 7.84], p: 3,
    w: "Walter Eucken, Franz Böhm, Wilhelm Röpke, Ludwig Erhard", tx: "The Foundations of Economics (Eucken, 1940)", fr: [["classlib", "s"], ["christdem", "s"]],
    d: "Markets do not maintain themselves: a strong state must set and police the rules of competition — breaking cartels, keeping money stable — without steering the economy. Joined to social insurance, it became West Germany's 'social market economy'.",
    c: "Critics on the left: an economic constitution that puts budgets and central banks beyond democratic reach — a charge revived in the eurozone crisis. Libertarians find it too statist.", u: "w:Ordoliberalism" },
  { id: "keynes", n: "Keynes, The General Theory", k: "t", ln: "lib", yr: 1936, pl: "Cambridge", at: [52.21, 0.12], fr: [["mill", "s"], ["classlib", "x"]],
    d: "Markets can settle into mass unemployment; governments can and should manage demand to prevent it. Keynes meant to save capitalism from itself — and gave social liberals and social democrats their economics for forty years.", u: "w:The_General_Theory_of_Employment,_Interest_and_Money",
    ar: [5, "trade", "Europe", "Britain", "Keynes's General Theory"] },
  { id: "neolib", n: "Neoliberalism", f: "lib", x: 6.8, y: 0.8, s: [1.6, 2.2], ln: "lib", yr: 1947, pl: "Paris (1938) · Mont Pèlerin (1947) · Chicago", at: [46.47, 6.82], p: 1,
    w: "Friedrich Hayek, Milton Friedman, Ludwig von Mises; in office Thatcher and Reagan", tx: "The Road to Serfdom (Hayek, 1944); Capitalism and Freedom (Friedman, 1962)", fr: [["classlib", "s"], ["mises", "s"], ["keynes", "x"], ["ordolib", "s"]],
    d: "Competitive markets are the best processors of scattered knowledge and the surest guard of freedom: privatise, deregulate, free trade and capital, restrain unions, target inflation. The name was adopted at a Paris colloquium in 1938; today it is used mostly by critics.",
    c: "Critics: rising inequality, weakened labour and financial crises (2008); first applied under Pinochet's dictatorship. Defenders point to tamed inflation and the steep fall in world poverty since 1980.", u: "w:Neoliberalism",
    ar: [4, "trade", "Europe", "International", "The Mont Pèlerin Society: neoliberalism organises"] },
  { id: "objectivism", n: "Objectivism", f: "ltn", x: 8.7, y: -5.0, ln: "lib", yr: 1957, pl: "New York", at: [40.71, -74.01], p: 3,
    w: "Ayn Rand", tx: "Atlas Shrugged (1957); The Virtue of Selfishness (1964)", fr: [["classlib", "s"], ["ml", "x", "Rand left Soviet Russia in 1926"]],
    d: "Reason is man's only guide, rational self-interest his proper morality, and laissez-faire capitalism the only system fit for it. Altruism as a duty is the root of collectivism. Rand rejected the label 'libertarian'.",
    c: "Critics: academic philosophers largely dismiss its arguments; conservatives such as Whittaker Chambers condemned its atheism and its contempt for the weak.", u: "w:Objectivism" },
  { id: "libertarian", n: "Libertarianism", f: "ltn", x: 8.0, y: -7.0, ln: "lib", yr: 1971, pl: "Vienna → New York → Colorado", at: [38.83, -104.82], p: 1,
    w: "Robert Nozick, Ludwig von Mises, Friedrich Hayek, Milton Friedman", tx: "Anarchy, State, and Utopia (Nozick, 1974)", fr: [["classlib", "s"], ["mises", "s"], ["indanarch", "s"]],
    d: "Each person owns themselves and what they justly acquire. The only legitimate state is a 'night-watchman' limited to protection against force and fraud; taxation for redistribution is akin to forced labour. The US Libertarian Party was founded in 1971.",
    c: "Critics: historical property titles are rarely just; markets alone under-provide public goods and leave the unlucky to charity; private power can coerce as surely as public.", u: "s:libertarianism" },
  { id: "ancap", n: "Anarcho-capitalism", f: "ltn", x: 9.6, y: -9.5, ln: "lib", yr: 1973, pl: "New York", at: [40.71, -74.01], p: 1,
    w: "Murray Rothbard, David Friedman; precursor Gustave de Molinari (1849)", tx: "For a New Liberty (Rothbard, 1973)", fr: [["libertarian", "s"], ["indanarch", "s"], ["mises", "s"]],
    d: "Abolish the state entirely and let courts, police and defence be supplied by competing firms under a principle of non-aggression. Every good, law included, is better produced by markets.",
    c: "Critics: left anarchists deny it is anarchism at all, since it keeps bosses and landlords; others predict that competing protection agencies end as warlords or as a new state.", u: "w:Anarcho-capitalism" },

  /* ───────────── CONSERVATISM & REACTION ───────────── */
  { id: "hobbes", n: "Hobbes, Leviathan", k: "t", ln: "con", yr: 1651, pl: "written in Paris exile, printed in London", at: [51.51, -0.13],
    d: "Without a sovereign, life is a war of all against all. People therefore agree to obey an undivided power in exchange for peace: order comes before liberty.", u: "w:Leviathan_(Hobbes_book)" },
  { id: "absolutism", n: "Absolutism (divine right)", f: "con", x: 5.9, y: 9.5, ln: "con", yr: 1680, pl: "Versailles", at: [48.80, 2.12], p: 2,
    w: "Jean Bodin, Robert Filmer, Bishop Bossuet; Louis XIV", tx: "Patriarcha (Filmer, 1680); Politics Drawn from Holy Scripture (Bossuet, 1709)", fr: [["hobbes", "s"]],
    d: "The monarch's authority comes from God, not from the people, and answers to God alone; sovereignty cannot be divided. Subjects owe obedience as children owe a father.",
    c: "Critics: Locke's First Treatise was written to refute Filmer; 1688, 1776 and 1789 were revolutions against it.", u: "w:Absolute_monarchy" },
  { id: "burke", n: "Traditionalist conservatism", f: "con", x: 4.4, y: 3.4, ln: "con", yr: 1790, pl: "London", at: [51.51, -0.13], p: 1,
    w: "Edmund Burke; later Coleridge, Oakeshott, Russell Kirk", tx: "Reflections on the Revolution in France (1790)", fr: [["leftright", "x", "written against the Revolution"], ["classlib", "s", "Burke was a Whig and a friend of Adam Smith"]],
    d: "Society is a partnership of the dead, the living and the unborn. Inherited institutions hold more wisdom than any theorist's blueprint; reform should be gradual, liberty ordered, and abstract 'rights of man' distrusted.",
    c: "Critics: Paine replied that the dead have no authority over the living; the argument can defend any privilege that happens to be old.", u: "b:conservatism",
    ar: [5, "religion", "Europe", "Britain", "Burke's Reflections: conservatism finds its voice"] },
  { id: "reaction", n: "Counter-revolution (throne and altar)", f: "con", x: 5.3, y: 7.7, ln: "con", yr: 1797, pl: "Lausanne — de Maistre in exile", at: [46.52, 6.63], p: 3, ref: "vienna1815",
    w: "Joseph de Maistre, Louis de Bonald, Donoso Cortés; Metternich in practice", tx: "Considerations on France (1797)", fr: [["absolutism", "s"], ["leftright", "x"]],
    d: "The Revolution was a satanic rupture. Order rests on throne, altar and hierarchy — and, in the last resort, on the executioner. Authority must be restored whole, with the Pope above kings.",
    c: "Critics: liberals and democrats of every stripe. Isaiah Berlin read de Maistre as a forerunner of fascism — a judgement other historians dispute.", u: "w:Joseph_de_Maistre" },
  { id: "onenation", n: "One-nation conservatism", f: "con", x: 2.8, y: 3.9, ln: "con", yr: 1845, pl: "London", at: [51.51, -0.13], p: 3,
    w: "Benjamin Disraeli; in the same vein, Bismarck's social insurance (1883–89)", tx: "Sybil, or The Two Nations (1845)", fr: [["burke", "s"], ["chartism", "x"]],
    d: "The privileged owe a duty to the poor. Paternalist reform — factory acts, housing, a wider franchise — binds rich and poor into one nation and takes the wind from socialism's sails.",
    c: "Critics: socialists called it a bribe to keep property safe (Bismarck said as much); free-market conservatives later blamed it for the post-war 'consensus'.", u: "w:One-nation_conservatism" },
  { id: "christdem", n: "Christian democracy", f: "con", x: 1.6, y: 2.5, ln: "con", yr: 1891, pl: "Rome", at: [41.90, 12.45], p: 1,
    w: "Pope Leo XIII, Luigi Sturzo, Jacques Maritain, Konrad Adenauer, Alcide De Gasperi, Robert Schuman", tx: "Rerum Novarum (1891)", fr: [["onenation", "s"], ["marxism", "x", "Rerum Novarum answers socialism"], ["classlib", "x"]],
    d: "Between liberal individualism and socialist collectivism: private property with social obligations, a just wage, unions, the family, and 'subsidiarity' — decisions taken at the lowest level able to take them. Its parties rebuilt Western Europe after 1945 and founded the European Communities.",
    c: "Critics: secular liberals object to its social conservatism; the left sees a brake on redistribution; Italy's Christian Democrats ended in corruption scandals (1992–94).", u: "w:Christian_democracy",
    ar: [4, "religion", "Europe", "Papacy", "Rerum Novarum: the Church answers socialism"] },
  { id: "distributism", n: "Distributism", f: "con", x: -0.6, y: 1.5, ln: "con", yr: 1912, pl: "London", at: [51.51, -0.13], p: 3,
    w: "Hilaire Belloc, G. K. Chesterton", tx: "The Servile State (Belloc, 1912)", fr: [["christdem", "s"]],
    d: "Capitalism's fault is too few capitalists: spread productive property — land, workshops, tools — as widely as possible among families, guilds and cooperatives. Neither big business nor the big state.",
    c: "Critics: nostalgic for a medieval world that never was, with no plan for heavy industry. Marginal in practice, though cooperatives such as Mondragón cite it.", u: "w:Distributism" },
  { id: "neocon", n: "Neoconservatism", f: "con", x: 6.4, y: 5.2, ln: "con", yr: 1965, pl: "New York", at: [40.71, -74.01], p: 3,
    w: "Irving Kristol, Norman Podhoretz, Jeane Kirkpatrick, Paul Wolfowitz", tx: "The Public Interest (journal, 1965)", fr: [["sociallib", "x"], ["trotskyism", "x"], ["burke", "s"]],
    d: "Former liberals and leftists 'mugged by reality': sceptical of social engineering at home, confident that American power should defend and spread democracy abroad, and insistent on the moral foundations of capitalism.",
    c: "Critics: the Iraq War (2003) is charged to its account; paleoconservatives call it Wilsonian adventurism; the left notes several founders' Trotskyist youth.", u: "w:Neoconservatism" },
  { id: "natcon", n: "National conservatism & right-wing populism", f: "con", x: 4.1, y: 6.3, ln: "con", yr: 1972, ap: 1, pl: "Paris (Front National, 1972) and many later centres", at: [48.86, 2.35], p: 2,
    w: "Jean-Marie Le Pen, Viktor Orbán; writers Patrick Buchanan, Yoram Hazony", fr: [["burke", "s"], ["nationalism", "s"], ["populism", "s"], ["neolib", "x"]],
    d: "The nation-state, its borders, majority culture and religion come before both free markets and liberal individualism: restrict immigration, resist supranational bodies, protect national industry, and speak for 'the people' against cosmopolitan elites.",
    c: "Critics: where it governs, minority rights, press freedom and judicial independence erode, and it shades into the far right. Supporters say it restores democratic consent on questions that elites had closed.", u: "w:National_conservatism" },
  { id: "newright", n: "Thatcherism & the New Right", f: "con", x: 7.9, y: 3.9, ln: "con", yr: 1975, pl: "London · Washington", at: [51.51, -0.13], p: 2,
    w: "Margaret Thatcher, Keith Joseph, Ronald Reagan", tx: "The Right Approach (1976)", fr: [["neolib", "s"], ["burke", "s"], ["onenation", "x"]],
    d: "'The free economy and the strong state': neoliberal economics — privatisation, monetarism, curbing the unions — joined to social traditionalism, law and order, and national assertion.",
    c: "Critics: deindustrialised regions and wider inequality; one-nation Tories called it un-conservative. Supporters credit it with ending inflation and industrial paralysis, and with helping to win the Cold War.", u: "w:Thatcherism" },

  /* ───────────── NATIONALISM · FASCISM · THE RADICAL RIGHT ───────────── */
  { id: "nationalism", n: "Nationalism", f: "nat", xc: 1, span: [-6, -2, 7, 9.8], ln: "rad", yr: 1807, pl: "Berlin · Paris · Genoa", at: [52.52, 13.40], p: 1,
    w: "Herder, Fichte, Mazzini, Renan", tx: "Addresses to the German Nation (Fichte, 1808); What Is a Nation? (Renan, 1882)", fr: [["leftright", "s"], ["rousseau", "s"], ["jacobinism", "s", "the nation in arms"]],
    d: "Humanity is divided into nations, each entitled to govern itself; political and national boundaries should coincide. Born on the left with the French Revolution's 'nation in arms', it has since married liberalism, socialism, conservatism and fascism alike.",
    c: "Why it has no single place on the compass: Mazzini's liberal republicanism, Nyerere's socialism and Hitler's racism were all nationalisms. Critics from Marx to Lord Acton saw in it the solvent of class solidarity or of liberty; its defenders, the precondition of democracy.", u: "s:nationalism" },
  { id: "maurras", n: "Action française: 'integral nationalism'", k: "o", ln: "rad", yr: 1899, pl: "Paris", at: [48.86, 2.35], fr: [["reaction", "s"], ["nationalism", "s"]],
    d: "Charles Maurras fused monarchism, Catholicism-as-order and antisemitism into a street movement born of the Dreyfus Affair — the laboratory in which the old counter-revolution learned mass politics.", u: "w:Action_Française" },
  { id: "sorel", n: "Sorel, Reflections on Violence", k: "t", ln: "rad", yr: 1908, pl: "Paris", at: [48.86, 2.35], fr: [["syndicalism", "s"], ["marxism", "x"]],
    d: "The general strike is a 'myth' that need not be true to move men; violence regenerates a decadent society. Written for revolutionary syndicalists, read with profit by Mussolini — the bridge along which part of the far left crossed to fascism.", u: "w:Reflections_on_Violence" },
  { id: "fascism", n: "Fascism", f: "aut", x: 1.8, y: 9.2, ln: "rad", yr: 1919, pl: "Piazza San Sepolcro, Milan", at: [45.46, 9.19], p: 1, ref: "marchonrome",
    w: "Benito Mussolini, Giovanni Gentile, Alfredo Rocco", tx: "The Doctrine of Fascism (1932)",
    fr: [["nationalism", "s"], ["sorel", "s"], ["maurras", "s"], ["syndicalism", "p", "national syndicalists who chose the nation over the class in 1914–15"], ["marxism", "x"], ["classlib", "x"]],
    d: "The nation is an organic whole that realises itself in a total state under one leader — everything within the state, nothing outside it. Class conflict is abolished by decree in corporations of employers and workers; violence, war and empire regenerate the nation.",
    c: "Critics: dictatorship, aggressive war (Ethiopia 1935, 1940–45), racial laws (1938) and complicity in the Holocaust. Marxists called it capitalism's emergency regime; liberals, communism's twin ('totalitarianism'). Mussolini began as a revolutionary socialist.", u: "b:fascism",
    ar: [5, "law", "Europe", "Italy", "Fascism founded in Milan"] },
  { id: "natbol", n: "National Bolshevism & Strasserism", f: "aut", x: -4.6, y: 9.2, ln: "rad", yr: 1919, pl: "Hamburg · Berlin", at: [53.55, 9.99], p: 3,
    w: "Heinrich Laufenberg, Ernst Niekisch, Gregor & Otto Strasser", fr: [["councilcom", "p", "Hamburg left communists, expelled from the KAPD in 1920"], ["nationalism", "s"]],
    d: "Ultranationalism joined to anti-capitalism: a national revolution, nationalised industry and an alliance of Germany with Soviet Russia against the West. The Strassers led the Nazi Party's anti-capitalist wing until Hitler purged it (1934).",
    c: "Critics: rejected by communists (Lenin condemned the Hamburg group in 1920) and by Hitler alike. Always marginal, though revived by post-Soviet extremists.", u: "w:National_Bolshevism" },
  { id: "nazism", n: "National Socialism (Nazism)", f: "aut", x: 3.3, y: 9.7, ln: "rad", yr: 1920, pl: "Munich", at: [48.14, 11.58], p: 1, ref: "hitler33",
    w: "Adolf Hitler, Alfred Rosenberg, Joseph Goebbels", tx: "25-Point Programme (1920); Mein Kampf (1925)", fr: [["fascism", "s"], ["nationalism", "s"], ["natbol", "x", "the Strasser wing, purged in 1934"]],
    d: "Fascism fused with biological racism: history is a struggle of races, the 'Aryan' people need living space in the east, and Jews are cast as the universal enemy. The Leader's will is law. Private ownership was kept but bent to the state's war aims.",
    c: "It launched the Second World War in Europe and murdered six million Jews, with Roma, disabled people, Soviet prisoners and others. Its 'socialism' is a name: unions and the left were destroyed first. The War Room holds the record.", u: "w:Nazism" },
  { id: "showa", n: "Shōwa statism (Japanese militarism)", f: "aut", x: 4.9, y: 8.8, ln: "rad", yr: 1932, ap: 1, pl: "Tokyo", at: [35.68, 139.69], p: 3,
    w: "Kita Ikki, Araki Sadao, Tōjō Hideki", tx: "An Outline Plan for the Reorganisation of Japan (Kita, 1919)", fr: [["nationalism", "s"], ["fascism", "s"]],
    d: "The divine Emperor embodies the national polity (kokutai) and the army is its purest servant. Party politics and Western liberalism are to be swept away, the economy mobilised, and Asia 'liberated' under Japanese leadership.",
    c: "Critics: aggressive war from Manchuria (1931) to the Pacific, with atrocities such as Nanjing (1937). Scholars dispute whether 'fascism' fits a regime with no mass party and no single dictator.", u: "w:Statism_in_Shōwa_Japan" },
  { id: "falangism", n: "Falangism & Francoism", f: "aut", x: 3.5, y: 8.0, ln: "rad", yr: 1933, pl: "Madrid", at: [40.42, -3.70], p: 3, ref: "spanishcivil",
    w: "José Antonio Primo de Rivera, Francisco Franco", tx: "The Twenty-Seven Points of the Falange (1934)", fr: [["fascism", "s"], ["reaction", "s"], ["syndicalism", "x"]],
    d: "Spanish 'national syndicalism': one nation, one party, state-run unions, the Catholic faith and empire. Franco merged the Falange with monarchists and the Church into a military-clerical dictatorship (1939–75).",
    c: "Critics: a civil-war victory followed by tens of thousands of executions and decades of repression. Historians debate whether Franco's regime was fascist or conservative-authoritarian with fascist trappings.", u: "w:Falangism" },

  /* ───────────── RELIGIOUS, GREEN & CROSS-CUTTING CURRENTS ───────────── */
  { id: "feminism", n: "Feminism", f: "nat", xc: 1, span: [-9.5, -9.5, 6, 2], ln: "oth", yr: 1792, pl: "London · Paris · Seneca Falls", at: [51.51, -0.13], p: 1, ref: "suffrage",
    w: "Mary Wollstonecraft, Olympe de Gouges, Elizabeth Cady Stanton, Clara Zetkin, Alexandra Kollontai, Simone de Beauvoir", tx: "A Vindication of the Rights of Woman (1792); The Second Sex (1949)", fr: [["radicalism", "s"], ["classlib", "s"], ["leftright", "s", "de Gouges's Declaration of the Rights of Woman (1791)"]],
    d: "Women are entitled to the same rights, standing and freedom as men, and their subordination is social, not natural. Liberal feminists sought the vote and equal law; socialist feminists tied emancipation to the end of class society; radical feminists named patriarchy itself.",
    c: "Why it has no single place on the compass: there are liberal, socialist, anarchist, conservative and libertarian feminisms. Critics range from traditionalists defending separate roles to feminists who fault its earlier waves for speaking mainly for white, middle-class women.", u: "w:Feminism",
    ar: [5, "law", "Europe", "Britain", "Wollstonecraft's Vindication of the Rights of Woman"] },
  { id: "anticolonial", n: "Anti-colonial nationalism & Pan-Africanism", f: "nat", xc: 1, span: [-9, -7, 3, 9], ln: "oth", yr: 1885, pl: "Bombay · London · Bandung", at: [18.94, 72.83], p: 2, ref: "bandung",
    w: "Dadabhai Naoroji, Sun Yat-sen, W. E. B. Du Bois, Kwame Nkrumah, Sukarno, Frantz Fanon", tx: "The Wretched of the Earth (Fanon, 1961)", fr: [["nationalism", "s"], ["leninism", "s", "Imperialism (1916) and the Comintern's support for colonial revolt"], ["classlib", "s"]],
    d: "Peoples ruled by empires are nations with the right to rule themselves; political independence must be completed by economic and cultural independence. From the Indian National Congress (1885) to Bandung (1955) it borrowed freely from liberalism, Marxism and religion.",
    c: "Why it has no single place on the compass: Gandhi, Ho Chi Minh, Nasser and Nehru were all anti-colonial nationalists. Critics note how often liberation movements became one-party states.", u: "w:Decolonization" },
  { id: "populism", n: "Populism", f: "nat", xc: 1, span: [-7, -1, 6, 8], ln: "oth", yr: 1892, pl: "Omaha, Nebraska", at: [41.26, -95.93], p: 2,
    w: "The US People's Party; the Russian Narodniks", tx: "The Omaha Platform (1892)", fr: [["radicalism", "s"], ["narodnik", "s"]],
    d: "Politics is a struggle between a virtuous 'people' and a corrupt 'elite'. It is a style and a thin ideology rather than a programme: the Omaha Platform demanded public railways and silver money; later populisms have been agrarian, socialist, nationalist and neoliberal.",
    c: "Why it has no single place on the compass: there are populisms of left and right. Critics say that claiming to be the only voice of the people leaves no room for a legitimate opposition; defenders call it democracy's alarm bell.", u: "w:Populism" },
  { id: "zionism", n: "Zionism", f: "nat", xc: 1, span: [-6, -5, 6, 7], ln: "oth", yr: 1897, pl: "Vienna · Basel", at: [47.56, 7.59], p: 3,
    w: "Theodor Herzl, Ahad Ha'am, David Ben-Gurion, Ze'ev Jabotinsky", tx: "The Jewish State (Herzl, 1896)", fr: [["nationalism", "s"], ["hess", "s", "Rome and Jerusalem (1862)"]],
    d: "The Jews are a nation entitled to self-determination in their ancestral homeland. From the start it spanned the compass: Labour Zionists built socialist kibbutzim, Revisionists a nationalist right, religious Zionists a messianic wing.",
    c: "Why it has no single place on the compass: it is a national movement with left, right, secular and religious parties. Critics — Palestinians above all — hold that it was realised through dispossession (1948) and occupation; the Jewish Bund and many Orthodox opposed it from within.", u: "w:Zionism" },
  { id: "gandhism", n: "Gandhism", f: "grn", x: -5.2, y: -6.3, ln: "oth", yr: 1909, pl: "written at sea between London and South Africa", at: [-29.86, 31.02], p: 2, ref: "gandhi",
    w: "Mohandas Gandhi, Vinoba Bhave; influences Tolstoy, Ruskin, Thoreau", tx: "Hind Swaraj (1909)", fr: [["anticolonial", "s"], ["anarchocom", "s", "by way of Tolstoy's Christian anarchism"]],
    d: "Truth-force (satyagraha): non-violent non-cooperation can break any regime that rests on obedience. Self-rule begins with self-discipline; the good society is a federation of self-sufficient villages, wary of machinery and of the centralised state.",
    c: "Critics: Ambedkar charged that it preserved caste; Marxists called its 'trusteeship' a shield for landlords and mill-owners; modernisers like Nehru set the village economy aside. Its method outlived its economics — from King to Mandela.", u: "w:Gandhism" },
  { id: "kemalism", n: "Kemalism", f: "nat", x: -0.6, y: 6.6, ln: "oth", yr: 1923, pl: "Ankara", at: [39.93, 32.86], p: 3,
    w: "Mustafa Kemal Atatürk", tx: "Nutuk (the Great Speech, 1927); the Six Arrows (1931)", fr: [["nationalism", "s"], ["jacobinism", "s"]],
    d: "Republicanism, nationalism, populism, statism, secularism, reformism: a one-party modernising state that abolished sultanate and caliphate, replaced sharia with European codes, Latinised the alphabet and gave women the vote.",
    c: "Critics: authoritarian — reform by decree, Kurdish identity denied, religion driven from public life; the army long claimed the right to guard it by coup.", u: "w:Kemalism" },
  { id: "hindutva", n: "Hindutva", f: "nat", x: 2.6, y: 6.9, ln: "oth", yr: 1923, pl: "Ratnagiri · Nagpur", at: [21.15, 79.09], p: 3,
    w: "V. D. Savarkar, K. B. Hedgewar, M. S. Golwalkar", tx: "Essentials of Hindutva (Savarkar, 1923)", fr: [["nationalism", "s"], ["anticolonial", "p"], ["gandhism", "x"]],
    d: "India is the homeland and holy land of the Hindus, who form one nation by blood and culture; the state should express that identity. Organised since 1925 through the RSS and, at the ballot box, the BJP.",
    c: "Critics: it makes Muslims and Christians second-class citizens and is charged with communal violence; Gandhi's assassin (1948) was a Hindu nationalist and former RSS member. Supporters call it the decolonisation of the Indian mind.", u: "w:Hindutva" },
  { id: "islamism", n: "Islamism", f: "nat", x: 0.4, y: 8.2, s: [2.4, 1.5], ln: "oth", yr: 1928, pl: "Ismailia, Egypt", at: [30.60, 32.27], p: 2, ref: "iranrev",
    w: "Hasan al-Banna, Abul A'la Maududi, Sayyid Qutb, Ruhollah Khomeini", tx: "Milestones (Qutb, 1964); Islamic Government (Khomeini, 1970)", fr: [["anticolonial", "s"], ["classlib", "x"], ["marxism", "x"]],
    d: "Islam is a complete political order, not only a faith: sovereignty belongs to God, and state and law should rest on sharia. It ranges from electoral parties (the Muslim Brotherhood, founded 1928) to Khomeini's rule of the jurist and to jihadist movements.",
    c: "Critics: where it rules, restrictions on women, religious minorities and dissent; many Muslim scholars reject its reading of sharia as a modern invention. Its economics run from welfare populism to free markets — hence the wide halo.", u: "w:Islamism" },
  { id: "peronism", n: "Peronism", f: "nat", x: -1.7, y: 5.2, ln: "oth", yr: 1945, pl: "Buenos Aires", at: [-34.60, -58.38], p: 3,
    w: "Juan and Eva Perón", tx: "The Twenty Truths of Justicialism (1950)", fr: [["populism", "s"], ["fascism", "s", "corporatism — without the war or the racial doctrine"], ["nationalism", "s"]],
    d: "A 'third position' between capitalism and communism: social justice, economic independence, political sovereignty. State-led industry, strong official unions and welfare, bound by loyalty to a leader.",
    c: "Critics: personalist and intolerant of opposition and the press; Perón admired Mussolini's corporatism. The movement has since housed everyone from left guerrillas to neoliberals.", u: "w:Peronism" },
  { id: "greens", n: "Green politics", f: "grn", x: -4.2, y: -5.2, ln: "oth", yr: 1972, pl: "Hobart · Wellington (1972) → Karlsruhe (1980)", at: [-42.88, 147.33], p: 1,
    w: "Petra Kelly; precursors Rachel Carson, E. F. Schumacher, Arne Næss", tx: "Silent Spring (1962); The Limits to Growth (1972)", fr: [["newleft", "s"], ["gandhism", "s"]],
    d: "Endless growth on a finite planet is impossible. The 'four pillars': ecological wisdom, social justice, grassroots democracy, non-violence. The first green parties formed in Tasmania and New Zealand in 1972; Die Grünen entered the Bundestag in 1983.",
    c: "Critics on the right: hostile to growth, nuclear power and industry. Critics on the left: a middle-class politics that asks the poor to consume less. Greens themselves divide into 'realists' and 'fundamentalists'.", u: "w:Green_politics" }
  ];

  const FAMILIES = {
    com: ["Marxism & communism", "#e5484d"],
    soc: ["Socialism & social democracy", "#f08fb0"],
    ana: ["Anarchism", "#c8ccd6"],
    grn: ["Green & non-violent", "#62c073"],
    lib: ["Liberalism", "#f2c94c"],
    ltn: ["Libertarian right", "#b48ef0"],
    con: ["Conservatism & Christian democracy", "#5b9be0"],
    aut: ["Fascism & the ultranationalist right", "#b57f52"],
    nat: ["Nationalism, populism & religious politics", "#35b8ad"]
  };
  /* lineage lanes, top to bottom */
  const LANES = [
    ["anc", "Communal & utopian tradition"],
    ["fr", "France · revolution & early socialism"],
    ["de", "Philosophy · Hegel & the materialists"],
    ["pe", "Political economy · British labour"],
    ["mx", "Marx & Engels · the trunk"],
    ["ref", "The reform road"],
    ["rev", "The revolutionary road"],
    ["dis", "Dissident & Western Marxism"],
    ["tri", "Asia · Africa · Latin America"],
    ["ana", "Anarchism"],
    ["lib", "Liberalism & libertarianism"],
    ["con", "Conservatism & reaction"],
    ["rad", "Nationalism · fascism · the radical right"],
    ["oth", "Religious, green & cross-cutting"]
  ];
  /* the four quadrants as ideology charts customarily colour them */
  const QUADS = [
    { k: "al", n: "Authoritarian Left", x: -1, y: 1, c: "#d2452f", d: "The state should own or command the economy, and should have wide powers over society to do it." },
    { k: "ar", n: "Authoritarian Right", x: 1, y: 1, c: "#4f8fd6", d: "Property and markets — or tradition and hierarchy — upheld by a strong state and a firm social order." },
    { k: "ll", n: "Libertarian Left", x: -1, y: -1, c: "#4fae6a", d: "Economic equality and common ownership, reached with as little coercive authority as possible." },
    { k: "lr", n: "Libertarian Right", x: 1, y: -1, c: "#9a78d6", d: "Free markets and private property, with the state small or absent in economy and private life alike." }
  ];
  const BASES = { w: "https://en.wikipedia.org/wiki/", b: "https://www.britannica.com/topic/", s: "https://plato.stanford.edu/entries/", m: "https://www.marxists.org/" };
  const url = c => { if (!c) return ""; if (/^https?:/.test(c)) return c; const k = c[0], r = c.slice(2); return encodeURI(BASES[k] + r) + (k === "s" ? "/" : ""); };
  const srcName = c => !c ? "" : c[0] === "w" ? "Wikipedia" : c[0] === "b" ? "Britannica" : c[0] === "s" ? "Stanford Encyclopedia of Philosophy" : c[0] === "m" ? "Marxists Internet Archive" : "source";

  /* ids under which `ar` nodes appear in the main archive (see src/data/events8.js) */
  const AID = { more: "utopia1516", babouvism: "equals1796", marxism: "manifesto1848", intl1: "firstintl", capital: "capital1867", rsdlp: "bolshevik1903",
    comintern: "comintern1919", ml: "onecountry1924", titoism: "titostalin1948", secretspeech: "secretspeech1956", sinosoviet: "sinosoviet1960",
    longmarch: "longmarch", mutualism: "proudhon1840", keynes: "keynes1936", neolib: "montpelerin1947", burke: "burke1790", christdem: "rerumnovarum",
    fascism: "fasci1919", feminism: "wollstonecraft1792" };
  N.forEach(n => { if (n.ar) n.aid = AID[n.id] || n.id; });

  window.ARCHIVUS_DOCTRINES = { nodes: N, families: FAMILIES, lanes: LANES, quads: QUADS, url: url, srcName: srcName };
})();
